package com.example

import com.example.ExamQuestionHelper.QSpec

internal object GeographyLiveExamLandformsBank {
  private fun q(t: String, s: String, c: String, d1: String, d2: String, d3: String, e: String) =
    QSpec(t, s, c, listOf(d1, d2, d3), e)

  fun landformQuestions(): List<QSpec> {
    val t = "භූ රූප විද්‍යාව, පාෂාණ හා භූ තැටි චලනය"
    return listOf(
      q(t, "පෘථිවි අභ්‍යන්තරයේ උණු වූ මැග්මා හෝ ලාවා සිසිල් වී ඝන වීමෙන් නිර්මාණය වන ප්‍රාථමික පාෂාණ වර්ගය කුමක්ද?",
        "ආග්නේය පාෂාණ (Igneous Rocks)", "අවසාදිත පාෂාණ (Sedimentary Rocks)", "විපරීත පාෂාණ (Metamorphic Rocks)", "කාබනික පාෂාණ (Organic Rocks)",
        "ග්‍රැනයිට් (Granite) හා බැසෝල්ට් (Basalt) ප්‍රධාන ආග්නේය පාෂාණ උදාහරණ වේ."),
      q(t, "පෘථිවි පෘෂ්ඨය මතට ගලා ආ ලාවා ඉක්මනින් සිසිල් වීමෙන් සෑදෙන සියුම් ස්ඵටික සහිත බාහිර ආග්නේය පාෂාණය කුමක්ද?",
        "බැසෝල්ට් (Basalt)", "ග්‍රැනයිට් (Granite)", "කිරිගරුඬ (Marble)", "ක්වාර්ට්සයිට් (Quartzite)",
        "සාගර කබොල ප්‍රධාන වශයෙන් බැසෝල්ට් පාෂාණවලින් සමන්විත වේ."),
      q(t, "පොළොව අභ්‍යන්තරයේ ගැඹුරේදී මැග්මා ඉතා සෙමින් සිසිල් වීම නිසා විශාල ස්ඵටික සහිතව සෑදෙන ආග්නේය පාෂාණය කුමක්ද?",
        "ග්‍රැනයිට් (Granite)", "බැසෝල්ට් (Basalt)", "හුණුගල් (Limestone)", "වැලිගල් (Sandstone)",
        "මහාද්වීපික කබොලේ බහුලව ඇති ග්‍රැනයිට් පාෂාණයේ ක්වාර්ට්ස් සහ ෆෙල්ඩ්ස්පාර් ස්ඵටික පැහැදිලිව පෙනේ."),
      q(t, "විවිධ ඛාදන කාරක මගින් ගෙනෙන අවසාදිත ද්‍රව්‍ය ස්තර වශයෙන් තැන්පත් වී සම්පීඩනය වීමෙන් සෑදෙන පාෂාණ වර්ගය කුමක්ද?",
        "අවසාදිත පාෂාණ (Sedimentary Rocks)", "ආග්නේය පාෂාණ (Igneous Rocks)", "විපරීත පාෂාණ (Metamorphic Rocks)", "ප්ලූටොනික පාෂාණ (Plutonic Rocks)",
        "වැලිගල් (Sandstone), හුණුගල් (Limestone), ශේල් (Shale) සහ ගල් අඟුරු අවසාදිත පාෂාණ වේ."),
      q(t, "පෘථිවියේ අතීත ජීවීන්ගේ පොසිල (Fossils) සහ ඛනිජ තෙල් හෝ ගල් අඟුරු බහුලව සුරැකී පවතින්නේ කුමන පාෂාණ වර්ගය තුළද?",
        "අවසාදිත පාෂාණ (Sedimentary Rocks)", "ආග්නේය පාෂාණ (Igneous Rocks)", "විපරීත පාෂාණ (Metamorphic Rocks)", "මැග්මා පාෂාණ (Magmatic Rocks)",
        "අවසාදිත පාෂාණ අධික තාපයකින් තොරව ස්තර වශයෙන් තැන්පත් වන නිසා පොසිල විනාශ නොවී ආරක්ෂා වේ."),
      q(t, "පවතින ආග්නේය හෝ අවසාදිත පාෂාණ පොළොව අභ්‍යන්තරයේ අධික තාපයට හා පීඩනයට ලක්වී දිය නොවී වෙනස් වීමෙන් සෑදෙන පාෂාණ කුමක්ද?",
        "විපරීත පාෂාණ (Metamorphic Rocks)", "ආග්නේය පාෂාණ (Igneous Rocks)", "අවසාදිත පාෂාණ (Sedimentary Rocks)", "බාහිර ලාවා පාෂාණ (Volcanic Rocks)",
        "ශ්‍රී ලංකාවේ භූමියෙන් 90% කට ආසන්න ප්‍රමාණයක් ප්‍රාග්-කේම්බ්‍රියානු විපරීත පාෂාණවලින් (Gneiss, Marble, Quartzite) සමන්විතය."),
      q(t, "හුණුගල් (Limestone) අධික තාපයට හා පීඩනයට ලක්වී විපරීත වීමෙන් සෑදෙන දැඩි විපරීත පාෂාණය කුමක්ද?",
        "කිරිගරුඬ (Marble)", "ස්ලේට් (Slate)", "ක්වාර්ට්සයිට් (Quartzite)", "නයිස් (Gneiss)",
        "ඉදිකිරීම් හා මූර්ති කලාවට භාවිත කරන කිරිගරුඬ හුණුගල්වල විපරීත ස්වරූපයයි."),
      q(t, "මැටි පාෂාණයක් වන ශේල් (Shale) පීඩනයට ලක්වී විපරීත වීමෙන් වහල සෙවිලි කිරීමට පවා ගන්නා තුනී පතුරු සහිත පාෂාණය කුමක්ද?",
        "ස්ලේට් (Slate)", "කිරිගරුඬ (Marble)", "බැසෝල්ට් (Basalt)", "ක්වාර්ට්සයිට් (Quartzite)",
        "වැලිගල් (Sandstone) විපරීත වීමෙන් ක්වාර්ට්සයිට් (Quartzite) ද ග්‍රැනයිට් විපරීත වීමෙන් නයිස් (Gneiss) ද සෑදේ."),
      q(t, "විවිධ ඛනිජ වර්ගවල සීරීම් දෘඪතාව මැනීම සඳහා 'මෝස් දෘඪතා පරිමාණයේ' (Mohs Hardness Scale) උපරිම අගය වන 10 හිමි ඛනිජය කුමක්ද?",
        "දියමන්ති (Diamond)", "ටැල්ක් (Talc)", "ක්වාර්ට්ස් (Quartz)", "මිනිරන් (Graphite)",
        "ටැල්ක් අවම දෘඪතාව (1) හා දියමන්ති උපරිම දෘඪතාව (10) දරයි."),
      q(t, "ඇල්ෆ්‍රඩ් වෙගනර් (Alfred Wegener) විසින් 1912 දී ඉදිරිපත් කරන ලද මහාද්වීප අතීතයේදී එකට තිබී වෙන්වී ගිය බව පැවසෙන න්‍යාය කුමක්ද?",
        "මහාද්වීපික ප්ලාවිත න්‍යාය (Continental Drift Theory)", "සාගර පතුල පැතිරීමේ න්‍යාය (Seafloor Spreading)", "භූ තැටි විභේදන න්‍යාය (Faulting Theory)", "ජල චක්‍ර සංසරණ න්‍යාය (Hydrological Theory)",
        "අතීතයේ සියලු මහාද්වීප එක්ව තිබූ සුපිරි මහාද්වීපය 'පැන්ජියා' (Pangaea) නම් විය."),
      q(t, "භූ තැටි (Tectonic Plates) පෘථිවි ප්‍රාවරණයේ ඉහළ අර්ධ-ද්‍රව ස්තරය (Asthenosphere) මත චලනය වීමට ශක්තිය සපයන ප්‍රධාන යාන්ත්‍රණය කුමක්ද?",
        "ප්‍රාවරණයේ සිදුවන තාප සංවහන ධාරා (Mantle Convection Currents)", "සාගර මතුපිට හමන වෙළඳ සුළං ප්‍රවාහ (Trade Wind Currents)", "චන්ද්‍රයාගේ ගුරුත්වාකර්ෂණ වඩදිය බලය (Lunar Tidal Forces)", "සෘතුමය මෝසම් වර්ෂාපතන චක්‍රය (Monsoon Rainfall Cycle)",
        "අභ්‍යන්තර තාපය නිසා උණුසුම් ද්‍රව්‍ය ඉහළ නැග පැතිරී සිසිල් වී පහළ බැසීම භූ තැටි ගෙන යයි."),
      q(t, "භූ තැටි දෙකක් එකිනෙකින් ඉවතට ඇදී යන (අපසාරී - Divergent) සීමාවක ප්‍රධාන වශයෙන්ම නිර්මාණය වන භූ ලක්ෂණය කුමක්ද?",
        "මධ්‍ය සාගරික වැටි සහ විභේද නිම්න (Mid-Ocean Ridges & Rift Valleys)", "මහාද්වීපික නැමි කඳු වැටි (Continental Fold Mountains)", "ගැඹුරු සාගර අගාධ සහ දූපත් චාප (Ocean Trenches & Island Arcs)", "වෙරළබඩ කොරල් දූපත් සහ කලපු (Coral Atolls & Lagoons)",
        "මධ්‍ය අත්ලාන්තික් වැටිය සහ නැගෙනහිර අප්‍රිකානු විභේද නිම්නය අපසාරී සීමාවන්ට උදාහරණ වේ."),
      q(t, "මහාද්වීපික භූ තැටි දෙකක් එකිනෙක ගැටෙන අභිසාරී (Convergent) සීමාවකදී නිර්මාණය වූ ප්‍රධානතම නැමි කඳු වැටිය (Fold Mountain) කුමක්ද?",
        "ඉන්දියානු හා යුරේසියානු තැටි ගැටීමෙන් සෑදුණු හිමාලය කඳු වැටිය", "අත්ලාන්තික් සාගරය මැද පිහිටි මධ්‍ය අත්ලාන්තික් වැටිය", "ජපානයේ සක්‍රීය කේතු ආකාර ෆුජි ගිනි කන්ද", "කැලිෆෝනියාවේ පිහිටි සැන් ඇන්ඩ්‍රියාස් පරිණාමන විභේදනය",
        "ඇල්ප්ස් කඳු වැටියද අප්‍රිකානු හා යුරේසියානු තැටි ගැටීමෙන් බිහිවූ නව නැමි කඳු වැටියකි."),
      q(t, "ඝනත්වයෙන් වැඩි සාගරික තැටියක් සැහැල්ලු මහාද්වීපික තැටියක් යටට ගිලා බැසීමේ (Subduction) ක්‍රියාවලියේදී සෑදෙන ගැඹුරු භූ ලක්ෂණය කුමක්ද?",
        "ගැඹුරු සාගර අගාධ සහ ගිනිකඳු කඳු වැටි", "මධ්‍ය සාගරික වැටි සහ විභේද නිම්න", "ගංගා මෝය ඩෙල්ටා සහ පිටාර තැන්න", "සමුද්‍ර දිය ඇලි සහ වෙරළ ප්‍රපාත",
        "ලොව ගැඹුරුම මරියානා අගාධය (මීටර් 11,000+) හා දකුණු ඇමරිකාවේ ඇන්ඩීස් කඳු වැටිය මෙසේ නිර්මාණය වී ඇත."),
      q(t, "භූ තැටි දෙකක් එකිනෙක පසු කරමින් සමාන්තරව ලිස්සා යන පරිණාමන (Transform) සීමාවකට ලෝක ප්‍රකට උදාහරණය කුමක්ද?",
        "කැලිෆෝනියාවේ සැන් ඇන්ඩ්‍රියාස් විභේදනය (San Andreas Fault)", "ආසියාවේ හිමාලය නැමි කඳු වැටිය (Himalayan Fold Range)", "නැගෙනහිර අප්‍රිකානු මහා විභේද නිම්නය (East African Rift)", "පැසිෆික් සාගරයේ මරියානා සාගර අගාධය (Mariana Trench)",
        "මෙවැනි සීමාවන්හි ගිනිකඳු විරල වුවද ඉතා ප්‍රබල නොගැඹුරු භූමිකම්පා බහුලව හටගනී."),
      q(t, "ලෝකයේ සක්‍රීය ගිනිකඳු වලින් 75% කට ආසන්න ප්‍රමාණයක් සහ භූමිකම්පාවලින් 90% ක් පමණ සිදුවන කලාපය කුමක්ද?",
        "පැසිෆික් සාගරය වටා පිහිටි පැසිෆික් ගිනි වළල්ල", "උතුරු අප්‍රිකාවේ පිහිටි ශුෂ්ක සහරා කාන්තාර කලාපය", "මහාද්වීප අභ්‍යන්තරයේ පිහිටි උතුරු යුරෝපීය තැන්න", "ආසියාවේ උතුරු කොටසේ පිහිටි සයිබීරියානු පළිහ",
        "පැසිෆික් සාගරය වටා පිහිටි ජපානය, ඉන්දුනීසියාව, පිලිපීනය, ඇලස්කාව සහ චිලී මෙම කලාපයට අයත්ය."),
      q(t, "භූමිකම්පාවක් පෘථිවි අභ්‍යන්තරයේ ආරම්භ වන නියම ලක්ෂ්‍යය සහ ඊට කෙළින්ම ඉහළින් පොළොව මතුපිට පිහිටි ලක්ෂ්‍යය පිළිවෙළින් කවරේද?",
        "නාභිය (Focus) සහ අපිකේන්ද්‍රය (Epicenter)", "ආවාටය (Crater) සහ මැග්මා කුටිය (Magma Chamber)", "විභේදනය (Fault) සහ සාගර අගාධය (Trench)", "සමෝච්චය (Contour) සහ ප්‍රපාත බෑවුම (Escarpment)",
        "භූමිකම්පාවෙන් වැඩිම හානිය සාමාන්‍යයෙන් අපිකේන්ද්‍රය අවට ප්‍රදේශයට සිදු වේ."),
      q(t, "භූ කම්පන තරංග (Seismic Waves) වාර්තා කිරීමට භාවිත කරන උපකරණය හා එම ප්‍රස්තාරය පිළිවෙළින් කුමක්ද?",
        "භූ කම්පන මානය (Seismograph) සහ සීස්මොග්‍රෑම් (Seismogram)", "වායු පීඩන මානය (Barometer) සහ බැරෝග්‍රෑම් (Barogram)", "සුළං වේග මානය (Anemometer) සහ ඇනිමෝග්‍රෑම් (Anemogram)", "ආර්ද්‍රතා මානය (Hygrometer) සහ හයිග්‍රොග්‍රෑම් (Hygrogram)",
        "පළමුව වේගවත් P (ප්‍රාථමික) තරංගද දෙවනුව S තරංගද පසුව විනාශකාරී L (පෘෂ්ඨීය) තරංගද පැමිණේ."),
      q(t, "භූමිකම්පාවක මුදා හරින ශක්ති විශාලත්වය මනින පරිමාණය හා හානි තීව්‍රතාව මනින පරිමාණය පිළිවෙළින් කුමක්ද?",
        "රිච්ටර් පරිමාණය සහ මර්කාලි පරිමාණය", "සැෆිර්-සිම්ප්සන් සහ බෝෆර්ට් පරිමාණය", "සෙල්සියස් සහ කෙල්වින් උෂ්ණත්ව පරිමාණය", "මෝස් දෘඪතා සහ පීඑච් පරිමාණය",
        "රිච්ටර් පරිමාණයේ එක් ඒකක වැඩිවීමක් යනු තරංග විස්තාරය 10 ගුණයකින් හා ශක්තිය ~32 ගුණයකින් වැඩි වීමකි."),
      q(t, "ඉතා ද්‍රවශීලී බැසෝල්ට් ලාවා සන්සුන්ව ගලා ගොස් පුළුල්, මෘදු බෑවුම් සහිතව නිර්මාණය කරන ගිනිකඳු වර්ගය කුමක්ද?",
        "පළිහ ගිනි කඳු (Shield Volcanoes)", "සංයුක්ත ගිනි කඳු (Composite Volcanoes)", "සින්ඩර් කේතු ගිනි කඳු (Cinder Cones)", "භූ තැටි විභේද නිම්න (Rift Valleys)",
        "හවායි දූපත් උණුසුම් ලක්ෂ්‍ය (Hotspot) මත බිහිවූ පළිහ ගිනිකඳු සඳහා ප්‍රසිද්ධය."),
      q(t, "ගිනිකඳු අළු ස්තර හා ඝන ලාවා ස්තර මාරුවෙන් මාරුවට තැන්පත් වී නිර්මාණය වන උස්, තියුණු බෑවුම් සහිත පිපිරුම්කාරී ගිනි කඳු කවරේද?",
        "සංයුක්ත ස්තර ගිනි කඳු (Stratovolcanoes)", "පළිහ ගිනි කඳු පද්ධති (Shield Volcanoes)", "ලාවා පැතලි සානු බිම් (Lava Plateaus)", "බාචන් අඩසඳ වැලි කඳු (Barchan Dunes)",
        "සංයුක්ත ගිනිකඳු අභිසාරී තැටි සීමාවල පිහිටන අතර ප්‍රචණ්ඩ පිපිරීම් ඇති කරයි."),
      q(t, "දැවැන්ත ගිනිකඳු පිපිරීමකින් පසු මැග්මා කුටිය හිස් වී ගිනි කන්දේ මුදුන ඇතුළට කඩා වැටීමෙන් සෑදෙන විශාල ආවාටමය අවපාතය කුමක්ද?",
        "කැල්ඩේරාව (Caldera)", "ඩෙල්ටාව (Delta)", "ෆියෝඩ් නිම්නය (Fjord)", "ඇටෝල් පරය (Atoll)",
        "මෙවැනි කැල්ඩේරාවල වැසි ජලය පිරී විශාල ක්‍රේටර්/කැල්ඩේරා විල් නිර්මාණය වේ."),
      q(t, "ගිනිකඳු ආශ්‍රිත කලාපවල (උදා: අයිස්ලන්තය, නවසීලන්තය) භූගත ජලය රත් වී වරින් වර උණු වතුර හා හුමාලය ඉහළට විදින ස්වාභාවික උල්පත් කුමක්ද?",
        "ගීසර (Geysers) සහ උණු දිය උල්පත්", "ආටීසියානු පීඩන ළිං (Artesian Wells)", "වෙරළබඩ කලපු සහ මෝය (Lagoons)", "ගංගා ඔක්ස්බෝ විල් (Oxbow Lakes)",
        "මෙම භූතාපජ ශක්තිය (Geothermal Energy) අයිස්ලන්තයේ විදුලි හා තාප උත්පාදනයෙන් වැඩි කොටසක් සපයයි."),
      q(t, "පාෂාණ මුල් ස්ථානයේදීම (In-situ) දේශගුණික සාධක මගින් කැබලි වීම හෝ රසායනිකව දිරාපත් වීම හඳුන්වන්නේ කුමන නමකින්ද?",
        "ජීර්ණය (Weathering)", "ඛාදනය (Erosion)", "ප්‍රවාහනය (Transportation)", "තැන්පත් වීම (Deposition)",
        "ඛාදනයේදී ද්‍රව්‍ය එක් තැනක සිට තවත් තැනකට චලනය වන නමුත් ජීර්ණයේදී පාෂාණ සිටි තැනම බිඳී යයි."),
      q(t, "කාන්තාරවල දහවල් අධික උණුසුමට ප්‍රසාරණය වීමත් රාත්‍රී සීතලට හැකිලීමත් නිසා පාෂාණවල පිටත ස්තර ලූණු පොතු මෙන් ගැලවී යාම කුමක්ද?",
        "පතුරු ගැලවීම (Exfoliation)", "තුහින පැලීම (Frost Shattering)", "කාබනීකරණය (Carbonation)", "ඔක්සිකරණය (Oxidation)",
        "මෙය භෞතික / යාන්ත්‍රික ජීර්ණයට (Physical Weathering) ප්‍රධාන උදාහරණයකි."),
      q(t, "ශීත කඳුකර ප්‍රදේශවල පාෂාණ පැලුම් තුළ ජලය රැඳී රාත්‍රියේදී අයිස් බවට පත්ව පරිමාව ප්‍රසාරණය වීමෙන් පාෂාණ කැඩී යාම කුමක්ද?",
        "තුහින ක්‍රියාව හෙවත් හිම පැලීම (Frost Shattering)", "පතුරු ගැලවීම හෙවත් තාප විපර්යාසය (Exfoliation)", "රසායනික ද්‍රාවණ ජීර්ණය (Solution Weathering)", "ශාක මූල යාන්ත්‍රික ක්‍රියාව (Root Wedging)",
        "කඳු බෑවුම් පාමුල මෙසේ කැඩී වැටෙන තියුණු ගල් කැබලි 'ටැලස් / ස්ක්‍රී' (Talus / Scree Slopes) සාදයි."),
      q(t, "වැසි ජලය වායුගෝලීය CO2 සමඟ මිශ්‍ර වී සාදන දුර්වල කාබොනික් අම්ලය මගින් හුණුගල් (CaCO3) දිය කර දැමීමේ රසායනික ජීර්ණ ක්‍රියාවලිය කුමක්ද?",
        "කාබනීකරණය (Carbonation)", "ඔක්සිකරණය (Oxidation)", "පතුරු ගැලවීම (Exfoliation)", "හිම පැලීම (Frost Action)",
        "කාබනීකරණය හේතුවෙන් කාර්ස්ට් (Karst) හුණුගල් ගුහා හා පොළොව යට ගංගා නිර්මාණය වේ."),
      q(t, "පාෂාණවල ඇති යකඩ ඛනිජ ජලය හා ඔක්සිජන් සමඟ ප්‍රතික්‍රියා කර මලකඩ පැහැති රතු-දුඹුරු ස්තර සාදමින් දුර්වල වීම කුමක්ද?",
        "ඔක්සිකරණය (Oxidation)", "හිම පැලීම (Frost Shattering)", "කාබනීකරණය (Carbonation)", "පතුරු ගැලවීම (Exfoliation)",
        "නිවර්තන තෙත් ප්‍රදේශවල රතු-කහ පොඩ්සොලික් හා රතු දුඹුරු පස් වර්ණ ගැන්වීමට ඔක්සිකරණය දායක වේ."),
      q(t, "ගුරුත්වාකර්ෂණ බලය යටතේ බෑවුමක පස් හා පාෂාණ කොටස් ඉතා සෙමින් වසර ගණනාවක් පුරා පහළට රූරා යාම කුමක්ද?",
        "පාංශු රූරා යාම (Soil Creep)", "වේගවත් මඩ ගලා යාම (Mudflow)", "ක්ෂණික පාෂාණ කඩා වැටීම (Rockfall)", "මහා පරිමාණ නායයෑම (Landslide)",
        "Mass Wasting හෙවත් ස්කන්ධ චලන අතරින් මන්දගාමීම ස්වරූපය Soil Creep වේ."),
      q(t, "ගංගාවක ඉහළ ගමන් මාර්ගයේ (Upper Course) සිරස් ඛාදනය (Vertical Erosion) ප්‍රබල වීම නිසා නිර්මාණය වන ප්‍රධාන නිම්න හැඩය කුමක්ද?",
        "V-හැඩැති නිම්නය හා දුර්ග (V-shaped Valley & Gorges)", "U-හැඩැති ග්ලැසියර නිම්නය (U-shaped Glacial Trough)", "පුළුල් පිටාර තැන්න (Wide Floodplain)", "මෝය ආශ්‍රිත ඩෙල්ටාව (Estuarine Delta)",
        "තද බෑවුමක් සහිතව ගලන ජලය පතුල කපා ගැඹුරු V-නිම්න හා දිය ඇලි සාදයි."),
      q(t, "දිය ඇල්ලක් (Waterfall) සෑදීමේදී බොහෝ විට දක්නට ලැබෙන ගංගා පතුලේ පාෂාණ සැකැස්ම කුමක්ද?",
        "උඩින් දැඩි ප්‍රතිරෝධී පාෂාණ ස්තරයකුත් යටින් මෘදු පහසුවෙන් ඛාදනය වන පාෂාණ ස්තරයකුත් පිහිටීම", "ගංගා පතුල සම්පූර්ණයෙන්ම ලිහිල් වැලි සහ මඩ ස්තරවලින් පමණක් සමන්විත වී පැවතීම", "මෘදු පාෂාණ ස්තරය උඩින් පිහිටා ඉතා දැඩි ආග්නේය පාෂාණ ස්තරය යටින් පිහිටා තිබීම", "ගංගා ඉවුරු දෙපස වසර පුරාම දිය නොවන ඝන ග්ලැසියර අයිස් තට්ටු පමණක් පැවතීම",
        "මෘදු පාෂාණය ඛාදනය වී යටි කැපීමෙන් දිය ඇල්ල පාමුල 'ප්‍රපාත තටාකයක්' (Plunge Pool) සෑදේ."),
      q(t, "ගංගාවක මැද හා පහළ ගමන් මාර්ගයේදී පාර්ශ්වික ඛාදනය හා තැන්පත් වීම නිසා ගංගාව වංගු ගැසී ගමන් කිරීම හඳුන්වන්නේ කුමන නමකින්ද?",
        "දියවැල් වංගු හෙවත් මියැන්ඩර් (Meanders)", "ගැඹුරු දුර්ග මාර්ග (Gorges)", "සිරස් V-හැඩැති නිම්න (V-Valleys)", "සෝපානමය දිය ඇලි (Cataracts)",
        "වංගුවේ පිටත ඉවුර ඛාදනය වන අතර (River Cliff) ඇතුළත ඉවුරේ රොන්මඩ තැන්පත් වේ (Slip-off Slope)."),
      q(t, "ගංගාවක දියවැල් වංගුවක් (Meander) බෙල්ල කැපී ප්‍රධාන ගංගාවෙන් වෙන්වී ගොස් සෑදෙන අඩසඳ හැඩැති විල කුමක්ද?",
        "ඔක්ස්බෝ විල හෙවත් ගොන්කුර විල (Oxbow Lake)", "ගිනිකඳු කැල්ඩේරා විල (Caldera Lake)", "ග්ලැසියර සර්ක් විල (Tarn Lake)", "වෙරළබඩ වැලි කලපුව (Coastal Lagoon)",
        "මහවැලි හා කැලණි ගංගා පහළ නිම්නවල පැරණි වංගු විල් ලක්ෂණ නිරීක්ෂණය කළ හැක."),
      q(t, "ගංගාවක් ගංවතුර අවස්ථාවලදී ඉවුරු පිටාර ගොස් ඉවුරු දෙපස රළු රොන්මඩ තැන්පත් වීමෙන් සෑදෙන ස්වාභාවික උස් වැටි මොනවාද?",
        "ස්වාභාවික ඉවුරු වැටි හෙවත් ලෙවී (Natural Levees)", "ග්ලැසියර අවසාදිත මොරේන් වැටි (Moraine Ridges)", "කාන්තාර බාචන් වැලි කඳු (Barchan Dunes)", "වෙරළබඩ සමුද්‍ර වැලි තුඩු (Sand Spits)",
        "මිසිසිපි හා කහ ගංගාව (Hwang Ho) දෙපස විශාල ස්වාභාවික ලෙවී වැටි දැකිය හැක."),
      q(t, "ගංගාවක් මුහුදට හෝ විලකට වැටෙන මෝයේදී ප්‍රවේගය අඩු වීමෙන් රොන්මඩ තැන්පත් වී සෑදෙන ත්‍රිකෝණාකාර භූ රූපය කුමක්ද?",
        "ඩෙල්ටාව (Delta)", "දුර්ග නිම්නය (Gorge)", "ප්‍රපාත තටාකය (Plunge Pool)", "විභේද නිම්නය (Rift Valley)",
        "ශ්‍රී ලංකාවේ බොහෝ ගංගා මෝයවල මුහුදු රළ හා දියවැල් ප්‍රබල නිසා විශාල ඩෙල්ටා වෙනුවට වැලි වැටි හා මෝය සෑදේ."),
      q(t, "ගංගාවක් වියළි කඳුකරයක සිට පැතලි තැනිතලාවකට එකවර ඇතුළු වන කඳු පාමුලදී රොන්මඩ විසිරී තැන්පත් වන පංකා හැඩැති භූ රූපය කුමක්ද?",
        "දියළු පංකාව (Alluvial Fan)", "ඔක්ස්බෝ විල (Oxbow Lake)", "සමුද්‍ර ගුහාව (Sea Cave)", "වැලි ටොම්බොලෝව (Tombolo)",
        "කඳුකරයේ ශීඝ්‍ර බෑවුමෙන් පසු ජල ප්‍රවේගය හදිසියේ අඩුවීම මෙම ත්‍රිකෝණාකාර පංකාව සාදයි."),
      q(t, "මුහුදු රළ ගැටී වෙරළබඩ ගල් කඳුවැටියක් කැඩී ගොස් සෑදෙන සිරස් පාෂාණ බිත්තිය හා ඒ පාමුල පැතලි ගල් තලාව පිළිවෙළින් කුමක්ද?",
        "මුහුදු ප්‍රපාතය සහ තරංග කපන ලද වේදිකාව", "වෙරළ වැලි වැටිය සහ නොගැඹුරු කලපුව", "මෝය ඩෙල්ටාව සහ ස්වාභාවික ලෙවී වැටිය", "වැලි තුඩුව සහ දූපත් යා කරන ටොම්බොලෝව",
        "මුහුදු ප්‍රපාතය ක්‍රමයෙන් පසුබසින විට පාමුල ඇති පැතලි පාෂාණ තට්ටුව පුළුල් වේ."),
      q(t, "වෙරළ තුඩුවක (Headland) දෙපස ඇති මුහුදු ගුහා එකට හමුවී ආරුක්කුවක් සෑදී එහි වහලය කඩා වැටුණු පසු මුහුදේ ඉතිරි වන තනි ගල් කුළුණ කුමක්ද?",
        "මුහුදු ටැඹ හෙවත් ස්ටැක් (Sea Stack)", "වෙරළබඩ නොගැඹුරු කලපුව (Lagoon)", "දිගු වෙරළ වැලි තීරුව (Sand Bar)", "ගංගා මෝය ඩෙල්ටාව (River Delta)",
        "Sea Stack තවදුරටත් ඛාදනය වී කුඩා ගල් කොටයක් බවට පත්වූ විට එය 'ස්ටම්ප්' (Sea Stump) නම් වේ."),
      q(t, "මුහුදු රළ මගින් වෙරළ දිගේ වැලි ප්ලාවිතයෙන් ගෙන යන වැලි එක් කෙළවරක් ගොඩබිමට සම්බන්ධව මුහුද දෙසට දිගු වී සෑදෙන වැලි තීරුව කුමක්ද?",
        "ස්පිට් හෙවත් වැලි තුඩුව (Sand Spit)", "සිරස් මුහුදු ප්‍රපාතය (Sea Cliff)", "ගිනිකඳු කැල්ඩේරාව (Caldera)", "ගංගා ඔක්ස්බෝ විල (Oxbow Lake)",
        "මෙවැනි වැලි තුඩුවක් විරුද්ධ ඉවුර දක්වා වැඩී මුහුදු බොක්කක් වසා දැමූ විට පිටුපසින් කලපුවක් (Lagoon) සෑදේ."),
      q(t, "වෙරළ ආසන්නයේ පිහිටි කුඩා දූපතක් ප්‍රධාන ගොඩබිමට සම්බන්ධ කරමින් තැන්පත් වන වැලි පාලම හඳුන්වන්නේ කුමන නමකින්ද?",
        "ටොම්බොලෝව (Tombolo)", "මියැන්ඩර් වංගුව (Meander)", "මෝය ඩෙල්ටාව (Delta)", "හුණුගල් ගුහාව (Karst Cave)",
        "මීට අමතරව යාපනය අර්ධද්වීපය දූපත් හා ප්‍රධාන ගොඩබිම අතර වැලි වැටිවලින් බැඳුණු භූ ලක්ෂණ පෙන්වයි."),
      q(t, "කාන්තාර ප්‍රදේශවල සුළඟින් ගෙන යන වැලි අංශු පොළොවට මීටර් 1–2 ක් ඉහළින් පාෂාණ කඳුවල පාදම ඝර්ෂණයෙන් කපා දැමීමෙන් සෑදෙන භූ රූපය කුමක්ද?",
        "හතු පාෂාණය (Mushroom Rock)", "හුණුගල් ගුහාව (Limestone Cave)", "ග්ලැසියර සර්ක් නිම්නය (Cirque)", "ගංගා මෝය ඩෙල්ටාව (Delta)",
        "සුළඟින් වැලි කැට පොළොවට ආසන්නයේ වැඩි වශයෙන් පාවෙන නිසා පාෂාණයේ යටි කොටස සිහින් වී හතු හැඩයක් ගනී."),
      q(t, "කාන්තාරයේ සුළං දිශාවට අනුව වැලි තැන්පත් වීමෙන් සෑදෙන අඩසඳ හැඩැති චලනය වන වැලි කන්ද කුමක්ද?",
        "බාචන් වැලි කන්ද (Barchan Dune)", "සර්ක් කුහරය (Cirque Basin)", "ස්වාභාවික ලෙවී වැටිය (Natural Levee)", "ග්ලැසියර මොරේන් වැටිය (Moraine)",
        "බාචන් වැලි කන්දක අං දෙක සැමවිටම සුළං හමන ඉදිරි දිශාව (Downwind) දෙසට දිගු වී පවතී."),
      q(t, "හුණුගල් ගුහාවක වහලයේ සිට පහළට වැඩෙන හිරිගල් කුළුණ හා බිම සිට ඉහළට වැඩෙන කුළුණ පිළිවෙළින් කුමක්ද?",
        "ස්ටැලක්ටයිට් හා ස්ටැලග්මයිට් කුළුණු", "සර්ක් කුහර හා ඇරේට් තියුණු වැටි", "ස්වාභාවික ලෙවී වැටි හා ගංගා ඩෙල්ටා", "හෝස්ට් උස් බිම් හා ග්‍රාබන් නිම්න",
        "ඒවා දෙක එකට හමුවී සම්බන්ධ වූ විට 'හුණුගල් කුළුණක්' (Limestone Pillar / Column) සෑදේ."),
      q(t, "මුදුන් හිම කඳුවල ග්ලැසියර ඛාදනය නිසා කඳු බෑවුමක ඇතිවන පුටු ආකාරයේ කුහර නිම්නය හඳුන්වන්නේ කෙසේද?",
        "සර්ක් හෙවත් කොරී (Cirque / Corrie)", "වියළි කාන්තාර නිම්නය (Wadi)", "වෙරළබඩ වැලි පාලම (Tombolo)", "අඩසඳ වැලි කන්ද (Barchan)",
        "ග්ලැසියරය දියවී ගිය පසු මෙම කුහරය තුළ 'ටාන්' (Tarn) නම් කඳුකර විලක් නිර්මාණය වේ."),
      q(t, "ග්ලැසියරයක් පෙර තිබූ V-හැඩැති ගංගා නිම්නයක් දිගේ ගමන් කර දෙපස හා පතුල ඛාදනය කිරීමෙන් පසු සෑදෙන නිම්න හැඩය කුමක්ද?",
        "U-හැඩැති ග්ලැසියර නිම්නය (U-shaped Valley)", "V-හැඩැති ගංගා නිම්නය (V-shaped Valley)", "ගංගා මියැන්ඩර් වංගුව (River Meander)", "හුණුගල් සින්ක්හෝල් කුහරය (Sinkhole)",
        "මුහුදු මට්ටම ඉහළ යාමෙන් මෙවැනි ගැඹුරු U-හැඩැති ග්ලැසියර නිම්න මුහුදු ජලයෙන් පිරුණු විට නෝර්වේ හි 'ෆියෝඩ්' (Fjords) සෑදේ."),
      q(t, "ග්ලැසියරයක් දියවී යන විට එය රැගෙන ආ විවිධ ප්‍රමාණයේ ගල්, බොරළු හා මැටි තැන්පත් වීමෙන් සෑදෙන භූ ලක්ෂණය කුමක්ද?",
        "ග්ලැසියර මොරේන් වැටි (Moraines)", "ගංගා මෝය ඩෙල්ටා (Deltas)", "සමුද්‍ර වැලි තුඩු (Sand Spits)", "නොගැඹුරු කොරල් පර (Coral Reefs)",
        "Lateral, Medial සහ Terminal Moraines ග්ලැසියර චලන සීමාවන් හඳුනා ගැනීමට උපකාරී වේ."),
      q(t, "අභ්‍යන්තර භූ බලවේග හේතුවෙන් සමාන්තර විභේදන දෙකක් අතර ඇති භූ කොටසක් පහළට ගිලා බැසීමෙන් සෑදෙන භූ රූපය කුමක්ද?",
        "විභේද නිම්නය හෙවත් ග්‍රාබන් (Rift Valley / Graben)", "කුට්ටි කන්ද හෙවත් හෝස්ට් (Block Mountain / Horst)", "අභිසාරී නැමි කඳු වැටිය (Fold Mountain)", "ද්‍රවශීලී පළිහ ගිනි කන්ද (Shield Volcano)",
        "විභේදන දෙක අතර මැද කොටස ඉහළට එසවුණු විට එය 'හෝස්ට්' හෙවත් කුට්ටි කන්දක් (Block Mountain) නම් වේ."),
      q(t, "පෘථිවි ඉතිහාසයේ වසර මිලියන ගණනක් පුරා ආග්නේය, අවසාදිත හා විපරීත පාෂාණ එකිනෙක බවට පරිවර්තනය වන අඛණ්ඩ ක්‍රියාවලිය කුමක්ද?",
        "පාෂාණ චක්‍රය (The Rock Cycle)", "ජල චක්‍රය (The Water Cycle)", "නයිට්‍රජන් චක්‍රය (Nitrogen Cycle)", "කාබන් චක්‍රය (Carbon Cycle)",
        "ජීර්ණය, තැන්පත් වීම, විපරීත වීම හා නැවත දියවී මැග්මා බවට පත්වීම හරහා පාෂාණ චක්‍රය ක්‍රියාත්මක වේ."),
      q(t, "පොළොව අභ්‍යන්තරයේ මැග්මා පෘෂ්ඨයට නොපැමිණ පවතින පාෂාණ ස්තර හරහා සිරස්ව පැතිරී ඝන වීමෙන් සෑදෙන ආග්නේය ආක්‍රමණය කුමක්ද?",
        "ඩයික් (Dyke)", "සිල් (Sill)", "ලාවා සානුව (Lava Plateau)", "ගීසරය (Geyser)",
        "පාෂාණ ස්තරවලට සමාන්තරව තිරස්ව ඝන වන ආග්නේය ආක්‍රමණය 'සිල්' (Sill) නම් වේ."),
      q(t, "ඉන්දියාවේ ඩෙකෑන් සානුව (Deccan Plateau) නිර්මාණය වීමට හේතු වූ භූ විද්‍යාත්මක ක්‍රියාවලිය කුමක්ද?",
        "පැළුම් විදාරණ මගින් බැසෝල්ට් ලාවා තට්ටු පිටතට ගලා තැන්පත් වීම", "මහාද්වීපික ග්ලැසියර මගින් පාෂාණ මතුපිට සමතලා ලෙස ඛාදනය වීම", "පැරණි නොගැඹුරු සාගරයක කොරල් පර හා හුණුගල් තට්ටු තැන්පත් වීම", "කාන්තාර සුළං මගින් ගෙන ආ සියුම් වැලි හා දූවිලි අංශු තැන්පත් වීම",
        "බැසෝල්ට් ලාවා දිරාපත් වීමෙන් කපු වගාවට ඉතා සුදුසු සාරවත් 'කළු කපු පස' (Regur Soil) සෑදී ඇත."),
      q(t, "සාගර පතුලේදී ප්‍රබල භූමිකම්පාවක්, ගිනිකඳු පිපිරීමක් හෝ සබ්මැරීන් නායයෑමක් නිසා සාගර ජල කුළුණම ක්ෂණිකව සෙලවීමෙන් හටගන්නා රළ කුමක්ද?",
        "සුනාමි රළ (Tsunami)", "සාමාන්‍ය වඩදිය රළ (High Tide)", "වෙරළබඩ සුළං රළ (Wind Waves)", "සාගර මතුපිට දියවැල් (Ocean Currents)",
        "2004 දෙසැම්බර් 26 සුමාත්‍රා භූමිකම්පාවෙන් හටගත් සුනාමිය ශ්‍රී ලංකාවට දැඩි හානි සිදු කළේය."),
      q(t, "කොරල් ජීවීන්ගේ කැල්සියම් කාබනේට් ඇටසැකිලි තැන්පත් වීමෙන් වෘත්තාකාර කලපුවක් වටා සෑදෙන කොරල් දූපත් වළල්ල කුමක්ද?",
        "ඇටෝල් හෙවත් වළලු පරය (Atoll)", "වෙරළ වැලි තුඩුව (Sand Spit)", "ගංගා මෝය ඩෙල්ටාව (River Delta)", "අඩසඳ වැලි කන්ද (Barchan Dune)",
        "නිවර්තන උණුසුම් (20°C–30°C), නොගැඹුරු, පැහැදිලි හා ලවණ සාගර ජලයේ කොරල් වර්ධනය වේ."),
      q(t, "ලෝකයේ විශාලතම බාධක කොරල් පරය වන 'මහා බාධක පරය' (Great Barrier Reef) පිහිටා ඇත්තේ කුමන රටට අයත් මුහුදේද?",
        "ඕස්ට්‍රේලියාව (ක්වීන්ස්ලන්ත ඊසානදිග වෙරළ)", "බ්‍රසීලය (දකුණු ඇමරිකානු නැගෙනහිර වෙරළ)", "ජපානය (පැසිෆික් සාගර දූපත් තීරය)", "එක්සත් රාජධානිය (උතුරු අත්ලාන්තික් වෙරළ)",
        "කිලෝමීටර් 2,300 ක් පමණ දිගැති මෙම පරය අභ්‍යවකාශයේ සිට පවා දැකගත හැකි ජෛව ව්‍යුහයකි."),
      q(t, "කඳුකර බෑවුමක කඩා වැටුණු ගල් කැබලි හා පස් අධික වර්ෂාවකින් සංතෘප්ත වී ඉතා වේගයෙන් පහළට ගලා යාම හඳුන්වන්නේ කුමක් ලෙසද?",
        "මඩ ගලා යාම හා නායයෑම (Mudflow & Landslide)", "සෙමින් සිදුවන පාංශු රූරා යාම (Soil Creep)", "හුණුගල් රසායනික කාබනීකරණය (Carbonation)", "ශීත කඳුකර තුහින පැලීම (Frost Shattering)",
        "අවිධිමත් බෑවුම් කැපීම් හා ජල අපවහන දුර්වලතා නායයෑම් අවදානම උග්‍ර කරයි."),
      q(t, "සක්‍රීය, නිද්‍රාශීලී (Dormant) සහ අක්‍රීය (Extinct) ගිනිකඳු අතරින් මෑත ඉතිහාසයේ නොපිපිරුණද අනාගතයේදී පිපිරීමේ හැකියාව පවතින ගිනිකන්ද කුමක්ද?",
        "නිද්‍රාශීලී ගිනි කන්ද (Dormant Volcano)", "අක්‍රීය හෙවත් මළ ගිනි කන්ද (Extinct Volcano)", "නිරන්තර සක්‍රීය ගිනි කන්ද (Active Volcano)", "සාගර පතුලේ උණුසුම් ලක්ෂ්‍යය (Submarine Hotspot)",
        "ජපානයේ ෆුජි කන්ද (Mt. Fuji) 1707 න් පසු නිද්‍රාශීලී තත්ත්වයේ පවතින ප්‍රකට ගිනිකන්දකි."),
      q(t, "විශාල ගංගාවක් සාගරයට වැටෙන විට දියවැල් හා උදම් බාදිය නිසා රොන්මඩ තැන්පත් නොවී මුහුදු ජලය ඇතුළු වන පුනීල හැඩැති ගං මෝය කුමක්ද?",
        "ගං මෝය හෙවත් එස්චුවරි (Estuary)", "කුරුලු පා හැඩැති ඩෙල්ටාව (Bird's-foot Delta)", "අඩසඳ ඔක්ස්බෝ විල (Oxbow Lake)", "ගැඹුරු ග්ලැසියර විල (Glacial Lake)",
        "මෝය ආශ්‍රිත කිවුල් දිය ජලය කඩොලාන පරිසර පද්ධති හා වරායන් සඳහා හිතකර වේ."),
      q(t, "මුහුදු වෙරළේ 'අනුරූප වෙරළ තීරුව' (Concordant Coastline) සහ 'අනුරූප නොවන වෙරළ තීරුව' (Discordant Coastline) වෙන් වන්නේ කුමක් මතද?",
        "වෙරළට සාපේක්ෂව දැඩි හා මෘදු පාෂාණ තීරු සමාන්තරව පිහිටන්නේද ලම්බකව පිහිටන්නේද යන්න මත", "වෙරළ තීරය අවට වාර්ෂික සාමාන්‍ය උෂ්ණත්වය හා සූර්ය විකිරණ ප්‍රමාණය වෙනස් වීම මත", "වෙරළබඩ කලාපයේ වෙසෙන මානව ජනගහන ඝනත්වය හා නාගරීකරණ මට්ටම වෙනස් වීම මත", "වෙරළ දෙසට හමන මෝසම් හා වෙළඳ සුළංවල වේගය හා දිශාව වෙනස් වීම මත",
        "ලම්බකව (Discordant) පිහිටි විට මෘදු පාෂාණ කැඩී බොකු (Bays) ද දැඩි පාෂාණ තුඩු (Headlands) ද සාදයි."),
      q(t, "පෘථිවි පෘෂ්ඨයේ ක්‍රියාත්මක වන 'අන්තර්ජාත බලවේග' (Endogenic Forces) සහ 'බහිර්ජාත බලවේග' (Exogenic Forces) අතර මූලික වෙනස කුමක්ද?",
        "අන්තර්ජාත බලවේග පොළොව ඇතුළතින් භූමිය උස් කරන අතර බහිර්ජාත බලවේග ජීර්ණය හා ඛාදනය මගින් භූමිය සමතලා කරයි", "අන්තර්ජාත හා බහිර්ජාත බලවේග දෙකම සාගර පතුලේ ජල ප්‍රවාහයන් මගින් පමණක් ක්‍රියාත්මක වේ", "බහිර්ජාත බලවේග පොළොව අභ්‍යන්තරයේ මැග්මා උණුසුමෙන් ක්‍රියාත්මක වී ගිනිකඳු හා කඳු වැටි නිර්මාණය කරයි", "අන්තර්ජාත බලවේග වායුගෝලයේ වර්ෂාපතනය හා සුළං හරහා ක්‍රියාත්මක වී පාෂාණ ජීර්ණය සිදු කරයි",
        "පෘථිවි භූ දර්ශනය මෙම ගොඩනැගීමේ හා ඛාදනයේ අඛණ්ඩ අරගලයක ප්‍රතිඵලයකි."),
      q(t, "ගංගාවක් තම ඛාදන ක්‍රියාවලියේදී ගඟ දිගේ ගෙන යන විශාල ගල් කැබලි ගඟ පතුල හා ඉවුරු සීරීමට ලක් කිරීම කුමක්ද?",
        "ඝර්ෂණ හෙවත් ඇබ්‍රේෂන් ඛාදනය (Abrasion)", "රසායනික ද්‍රාවණ ඛාදනය (Solution)", "ජල පීඩන ප්‍රහාරය (Hydraulic Action)", "ගල් කැබලි ගැටෙන සංඝට්ටනය (Attrition)",
        "ගඟේ ජලය පමණක් පාෂාණ පැලුම්වලට තදින් වැදී කැඩීම 'ජල ප්‍රහාරය' (Hydraulic Action) නම් වේ."),
      q(t, "ගංගා ජලයේ ගලා යන ගල් කැබලි එකිනෙක ගැටීමෙන් ක්‍රමයෙන් කුඩා වී සුමට බොරළු හා වැලි බවට පත්වීමේ ක්‍රියාවලිය කුමක්ද?",
        "සංඝට්ටනය (Attrition)", "ද්‍රාවණ ඛාදනය (Solution)", "රසායනික කාබනීකරණය (Carbonation)", "ඛනිජ ඔක්සිකරණය (Oxidation)",
        "එබැවින් ගංගාවක ඉහළ කොටසේ ඇති උල් සහිත විශාල ගල් පහළ මෝය වෙත යද්දී සුමට වැලි බවට පත්වේ."),
      q(t, "ශුෂ්ක කාන්තාර පරිසරවල සුළඟ මගින් වැලි හා දූවිලි ඉවතට ගසා ගෙන යාම නිසා ගල් කැබලි පමණක් ඉතිරි වූ සමතලා බිම කුමක්ද?",
        "කාන්තාර පදික වේදිකාව හෙවත් රෙග් (Reg)", "ලොයෙස් සාරවත් තැන්න (Loess Plain)", "ගංගා මෝය ඩෙල්ටාව (River Delta)", "වෙරළබඩ වැලි කලපුව (Coastal Lagoon)",
        "කුඩා අංශු ඉවත් වීමේ ක්‍රියාවලිය 'අපවාහනය' (Deflation) නම් වේ."),
      q(t, "කාන්තාර ආශ්‍රිතව සුළඟ මගින් දුර ඈතට ගෙන ගොස් තැන්පත් කරන ලද සියුම් කහ පැහැති සාරවත් දූවිලි පස් තට්ටු කුමක් ලෙස හැඳින්වේද?",
        "ලොයෙස් තැන්පතු (Loess)", "ග්ලැසියර මොරේන් (Moraine)", "ලැටරයිට් කබොල (Laterite)", "ගංගා දියළු පස (Alluvium)",
        "චීනයේ කහ ගංගාවේ (Yellow River) වර්ණයට හේතුව මෙම ලොයෙස් පස ගංගාවට එක් වීමයි."),
      q(t, "භූ විද්‍යාත්මක සාධක අනුව භූගත ජල ස්තරයක් (Aquifer) පොළොව යට රඳා පවතින්නේ කුමන පාෂාණ සැකැස්මක් මතද?",
        "ඉහළින් ජලය කාන්දු වන පාරගම්‍ය පාෂාණ ස්තරයක් හා යටින් අපාරගම්‍ය පාෂාණ ස්තරයක් පැවතීම", "උණුසුම් මැග්මා තට්ටුවක් මත ඍජුවම ගිනිකඳු අළු ස්තරයක් තැන්පත් වී තිබීම", "වසර පුරාම දිය නොවන ස්ථිර ග්ලැසියර අයිස් තට්ටුවක් මත වැලි තැන්පත් වී තිබීම", "ජලය කාන්දු නොවන ඝන ග්‍රැනයිට් පාෂාණ මුදුනක සියුම් මැටි ස්තරයක් පැවතීම",
        "මැටි හෝ ඝන ග්‍රැනයිට් වැනි අපාරගම්‍ය ස්තරයක් ජලය තවදුරටත් පහළට බැසීම වළක්වා ජලධරයක් සාදයි."),
      q(t, "භූ තැටි අතීතයේ සිට එකට තිබී බිඳී ගිය බවට ඇල්ෆ්‍රඩ් වෙගනර් ඉදිරිපත් කළ ප්‍රධාන සාක්ෂියක් නොවන්නේ කුමක්ද?",
        "ලෝකයේ සියලුම සාගර එකම සමාන ගැඹුරකින් හා උෂ්ණත්වයකින් යුක්ත වීම", "දකුණු ඇමරිකා හා අප්‍රිකා වෙරළ තීර ප්‍රහේලිකා කැබලි මෙන් එකට ගැලපීම", "මුහුදින් වෙන්වූ මහාද්වීප දෙකක එකම පුරාණ සත්ත්ව හා ශාක පොසිල හමුවීම", "නිවර්තන මහාද්වීප කිහිපයක පුරාණ ග්ලැසියර ඛාදන සලකුණු සමානව හමුවීම",
        "මෙසෝසෝරස් පොසිල හා ග්ලොසොප්ටෙරිස් ශාක පොසිල මහාද්වීප කිහිපයකින් හමු වී ඇත."),
      q(t, "1960 ගණන්වලදී හැරී හෙස් (Harry Hess) විසින් ඉදිරිපත් කරන ලද මහාද්වීප චලනය පැහැදිලි කළ නව සාගර විද්‍යාත්මක සංකල්පය කුමක්ද?",
        "මුහුදු පතුල පැතිරීම (Seafloor Spreading)", "නැමි කඳු ගොඩනැගීම (Orogeny)", "කොරියෝලිස් විචලන බලය (Coriolis Effect)", "සමුද්‍ර මෝසම් චක්‍රය (Monsoon Cycle)",
        "මධ්‍ය සාගර වැටිවල නව බැසෝල්ට් කබොල නිපදවෙන බැවින් වැටියට ආසන්න සාගර පතුල ලාබාලතම වේ."),
      q(t, "හුණුගල් ප්‍රදේශවල පොළොව මතුපිට ගංගාවක් ගමන් කරමින් සිට හදිසියේම පොළොව යට ගුහා පද්ධතියකට අතුරුදන් වන සිදුර කුමක්ද?",
        "ගිලා බැසීමේ සිදුර (Sinkhole)", "ප්‍රපාත දිය ඇල්ල (Waterfall)", "ඉවුරු ලෙවී වැටිය (Levee)", "උණු දිය ගීසරය (Geyser)",
        "කාර්ස්ට් භූ දර්ශනයේ ප්‍රධාන ජල වහන ලක්ෂණයක් වන්නේ මතුපිට ජලය භූගත මාර්ග ඔස්සේ ගැලීමයි."),
      q(t, "පාංශු පැතිකඩක (Soil Profile) ශාක වර්ධනයට වැඩිම පෝෂක හා හියුමස් (Humus) අඩංගු ඉහළම පාංශු ස්තරය කුමක්ද?",
        "A ක්ෂිතිජය හෙවත් මතුපිට පස (Topsoil)", "C ක්ෂිතිජය හෙවත් ජීර්ණ පාෂාණ ස්තරය", "R ක්ෂිතිජය හෙවත් නොදිරූ මව් පාෂාණය", "B ක්ෂිතිජය හෙවත් යටි ඛනිජ පස",
        "පාංශු ඛාදනය නිසා ඉවත් වන්නේ මෙම සාරවත් මතුපිට පස් ස්තරයයි."),
      q(t, "මුහුදු රළ ශක්තිය අඩු කරමින් වෙරළ තීරය ඛාදනයෙන් ආරක්ෂා කිරීම සඳහා යොදා ගන්නා 'මෘදු ඉංජිනේරු ක්‍රමයක්' (Soft Engineering) කුමක්ද?",
        "වෙරළට වැලි පිරවීම (Beach Nourishment) සහ කඩොලාන හා වෙරළ ශාක වගා කිරීම", "වෙරළ දිගේ විශාල කොන්ක්‍රීට් හා කළුගල් මුහුදු පවුරු බැඳීම", "වැලි ප්ලාවිතය වැළැක්වීමට මුහුද දෙසට කොන්ක්‍රීට් ගල් වැටි ඉදිකිරීම", "මුහුදු පතුලේ ස්වාභාවික කොරල්පර කඩා ඉවත් කර ගැඹුර වැඩි කිරීම",
        "මෘදු ඉංජිනේරු ක්‍රම ස්වාභාවික පරිසරය සමඟ සහයෝගයෙන් ක්‍රියා කරන අතර අතුරු ඛාදන අවම කරයි."),
      q(t, "වෙරළ දිගේ වැලි ප්ලාවිතය අල්ලා ගෙන පුළුල් වෙරළක් පවත්වා ගැනීමට මුහුද දෙසට ලම්බකව ඉදිකරන දැව හෝ ගල් වැටි කුමක්ද?",
        "ග්‍රොයින්ස් වැටි (Groynes)", "වැලි ටොම්බොලෝව (Tombolo)", "ගැබියන් ගල් කූඩ (Gabions)", "ගිනිකඳු කැල්ඩේරාව (Caldera)",
        "Groynes මගින් එක් පැත්තක වැලි රැස් කළද ඉදිරියෙන් පිහිටි වෙරළ තීරය වැලි නොලැබී ඛාදනය විය හැක."),
      q(t, "ගංගාව මගින් තැන්පත් කරන රොන්මඩ ප්‍රමාණය මුහුදු රළ මගින් ඉවත් කරන ප්‍රමාණයට වඩා වැඩි විට බිහිවන 'කුරුලු පා ඩෙල්ටාව' සඳහා උදාහරණය කුමක්ද?",
        "ඇමරිකාවේ මිසිසිපි ගංගා ඩෙල්ටාව", "එංගලන්තයේ තේම්ස් ගංගා මෝය", "ශ්‍රී ලංකාවේ කැලණි ගංගා මෝය", "අප්‍රිකාවේ කොංගෝ ගංගා මෝය",
        "නයිල් ගංගාව 'චාපාකාර ඩෙල්ටාවකට' (Arcuate Delta) සම්භාව්‍ය උදාහරණයකි."),
      q(t, "වෘක්ෂලතා සහ සතුන් පාෂාණ කැඩීමට හා ජීර්ණය කිරීමට දායක වීම හඳුන්වන්නේ කුමන ජීර්ණ වර්ගය ලෙසද?",
        "ජීව විද්‍යාත්මක ජීර්ණය (Biological Weathering)", "රසායනික ඔක්සිකරණය (Chemical Oxidation)", "භෞතික තුහින පැලීම (Frost Shattering)", "තාප පතුරු ගැලවීම (Thermal Exfoliation)",
        "ගස් මුල් පාෂාණ පැලුම් තුළට වැඩී පැලුම් පුළුල් කිරීම සහ ලයිකන මගින් අම්ල නිකුත් කිරීම මීට අයත්ය."),
      q(t, "අධික පාංශු ඛාදනය හේතුවෙන් කෘෂිකාර්මික ඉඩම්වල ගැඹුරු කාණු (Gullies) ඇතිවී භූමිය වගා කළ නොහැකි තත්ත්වයට පත්වීම කුමක්ද?",
        "ගැඹුරු දිය කඩිති ඛාදනය (Gully Erosion)", "මතුපිට තට්ටු ඛාදනය (Sheet Erosion)", "වෙරළබඩ සුළං ඛාදනය (Wind Erosion)", "රසායනික කාබනීකරණය (Carbonation)",
        "මුලින් සිහින් වැහි රේඛා (Rill Erosion) ලෙස ආරම්භ වී පසුව ගැඹුරු Gullies බවට වර්ධනය වේ."),
      q(t, "වෙරළට කෝණිකව හමා එන මුහුදු රළ පැමිණ පසුබැසීමේදී ඍජුවම පසුපසට යාම නිසා වෙරළ දිගේ වැලි ගමන් කරන ක්‍රියාවලිය කුමක්ද?",
        "වෙරළ දිගේ ප්ලාවිතය (Longshore Drift)", "ආටීසියානු භූගත ජල ගැලීම (Artesian Flow)", "පාෂාණ ද්‍රාවණ ක්‍රියාවලිය (Solution)", "සිරස් ගංගා ඛාදනය (Vertical Erosion)",
        "Swash (ඇලව ඉහළට යාම) හා Backwash (ගුරුත්වයෙන් සෘජුව පහළට බැසීම) කියත් දත් ආකාරයට වැලි ගෙන යයි."),
      q(t, "විශාල භූ කම්පනයකින් පසු ප්‍රධාන කම්පනයට වඩා කුඩා ප්‍රමාණයේ කම්පන දින හෝ සති ගණනක් පුරා ඇතිවීම හඳුන්වන්නේ කුමන නමකින්ද?",
        "පසු කම්පන (Aftershocks)", "පූර්ව කම්පන (Foreshocks)", "පෘෂ්ඨීය තරංග (Surface Waves)", "ලාවා ධාරා (Lava Flows)",
        "විභේදනයේ නව පිහිටීමට පාෂාණ ස්තර අනුගත වීමේදී මෙම පසු කම්පන ඇති වේ."),
      q(t, "ග්ලැසියර කඳු දෙකක සර්ක් (Cirques) පිටුපසට ඛාදනය වී එකිනෙකට ළං වීමෙන් සෑදෙන තියුණු පිහි තලයක් වැනි කඳු වැටිය කුමක්ද?",
        "ඇරේට් වැටිය (Arête)", "පිරමිඩීය ශිඛරය (Pyramidal Peak)", "ග්ලැසියර මොරේන් (Moraine)", "ඩ්‍රම්ලින් කඳු ගැටය (Drumlin)",
        "සර්ක් තුනක් හෝ වැඩි ගණනක් එකට හමුවන මධ්‍ය කඳු මුදුන 'හෝන් / පිරමිඩීය ශිඛරය' (උදා: මැටර්හෝන්) නම් වේ."),
      q(t, "ග්ලැසියරයක් යටින් ගලා යන අයිස් මගින් මොරේන් අවසාදිත සුමට ලෙස හැඩගස්වා සෑදෙන උඩු යටිකුරු කළ හැන්දක හැඩැති කඳු ගැට කවරේද?",
        "ඩ්‍රම්ලින්ස් (Drumlins)", "එස්කර් වැටි (Eskers)", "ස්ටැලක්ටයිට් (Stalactites)", "බාචන් වැලි කඳු (Barchans)",
        "ඩ්‍රම්ලින් රංචු වශයෙන් පිහිටන විට එය 'බිත්තර කූඩ භූ දර්ශනය' (Basket of Eggs Topography) ලෙස හැඳින්වේ."),
      q(t, "ග්ලැසියරයක් තුළින් හෝ යටින් ගලා ගිය දියවන ජල ඇළ මාර්ගවල තැන්පත් වූ වැලි හා බොරළු මගින් ඉතිරි වන දිගු වංගු සහිත වැටිය කුමක්ද?",
        "එස්කර් වැටිය (Esker)", "කේම් ගොඩැල්ල (Kame)", "මුහුදු ස්ටැක් (Sea Stack)", "බාචන් වැලි කන්ද (Barchan)",
        "මීටර් ගණනාවක් දිගැති එස්කර් වැටි ඇතැම් විට වගුරු බිම් හරහා පාරවල් තැනීමට භාවිත කෙරේ."),
      q(t, "ප්‍රධාන ග්ලැසියර නිම්නයකට වඩා නොගැඹුරින් කැපුණු අතු ග්ලැසියර නිම්නයක් ප්‍රධාන නිම්නයට ඉහළින් අවසන් වී සෑදෙන භූ ලක්ෂණය කුමක්ද?",
        "එල්ලෙන නිම්නය (Hanging Valley)", "විභේද නිම්නය (Rift Valley)", "මියැන්ඩර් නිම්නය (Meander Valley)", "කැන්යොන් දුර්ගය (Canyon)",
        "ග්ලැසියර දියවී ගිය පසු එල්ලෙන නිම්නවලින් පහළ ප්‍රධාන U-නිම්නයට අලංකාර දිය ඇලි කඩා හැලේ."),
      q(t, "මුහුදු රළ මගින් සෑදෙන 'නිර්මාණාත්මක තරංග' (Constructive Waves) වල ඇති ප්‍රධාන ලක්ෂණය කුමක්ද?",
        "ඉදිරි තරංග ප්‍රවාහය පසුබැසීමට වඩා ප්‍රබල බැවින් වෙරළේ වැලි තැන්පත් කර පුළුල් වෙරළ සෑදීම", "පසුබැසීමේ ප්‍රවාහය ප්‍රබල වී වෙරළ තීරය සම්පූර්ණයෙන් ඛාදනය කර ගැඹුරු කිරීම", "සාගර පතුලේ භූ කම්පන නිසා ගොඩබිම යට කරන දැවැන්ත සුනාමි රළ ඇති කිරීම", "වෙරළබඩ තුඩුවල පාදම වේගයෙන් කපා උස් මුහුදු ප්‍රපාත හා ගුහා නිර්මාණය කිරීම",
        "තරංග දිග වැඩි සහ සංඛ්‍යාතය අඩු (මිනිත්තුවකට 6–8) නිර්මාණාත්මක රළ සන්සුන් කාලවල පවතී."),
      q(t, "කුණාටු අවස්ථාවලදී ඇතිවන 'විනාශකාරී තරංග' (Destructive Waves) මගින් වෙරළ තීරයට සිදු කරන බලපෑම කුමක්ද?",
        "ප්‍රබල පසුබැසීම මගින් වෙරළෙන් වැලි මුහුදට ඇදගෙන ගොස් බෑවුම් සහිත වෙරළ ඛාදනය කිරීම", "සන්සුන්ව වෙරළ මත වැලි තැන්පත් කර පුළුල් සමතලා වැලි තීරු ගොඩනැගීම", "නොගැඹුරු උණුසුම් ජලයේ කොරල්පර වේගයෙන් වර්ධනය වීමට අවශ්‍ය පෝෂක සැපයීම", "ගංගා මෝය අසල රොන්මඩ තැන්පත් කර ත්‍රිකෝණාකාර ඩෙල්ටා නිර්මාණය කිරීම",
        "විනාශකාරී තරංගවල උස වැඩි අතර මිනිත්තුවකට තරංග 10–14 ක් පමණ ඉහළ සංඛ්‍යාතයකින් වෙරළට වදී."),
      q(t, "භූ තැටි විද්‍යාව අනුව පෘථිවි ඉතිහාසයේ සුපිරි මහාද්වීපය වූ 'පැන්ජියා' (Pangaea) බිඳී ගොස් දකුණු අර්ධගෝලයේ ඇතිවූ විශාල කොටස කුමක්ද?",
        "ගොන්ඩ්වානාලන්තය (Gondwanaland)", "ලෝරේෂියාව (Laurasia)", "පැන්තලසා සාගරය (Panthalassa)", "ටෙතිස් මුහුද (Tethys Sea)",
        "ශ්‍රී ලංකාව, ඉන්දියාව, අප්‍රිකාව, දකුණු ඇමරිකාව, ඕස්ට්‍රේලියාව සහ ඇන්ටාක්ටිකාව ගොන්ඩ්වානාලන්තයේ කොටස් විය."),
      q(t, "ලෝරේෂියාව (Laurasia) සහ ගොන්ඩ්වානාලන්තය වෙන් කරමින් අතීතයේ පිහිටි, පසුව ඉන්දියානු තැටිය ගැටීමෙන් හිමාලය බිහිවූ පුරාණ මුහුද කුමක්ද?",
        "ටෙතිස් මුහුද (Tethys Sea)", "මධ්‍යධරණී මුහුද (Mediterranean Sea)", "රතු මුහුද (Red Sea)", "බෙරිං මුහුද (Bering Sea)",
        "හිමාලය කඳු මුදුන්වලින් සාගර ජීවී පොසිල හමු වන්නේ ටෙතිස් මුහුදු පතුලේ අවසාදිත ඉහළට නැමීම නිසාය."),
      q(t, "ශ්‍රී ලංකාව පිහිටා ඇත්තේ කුමන ප්‍රධාන භූ තැටිය මතද?",
        "ඉන්දු-ඕස්ට්‍රේලියානු තැටිය (Indo-Australian Plate)", "පැසිෆික් සාගරික තැටිය (Pacific Plate)", "උතුරු ඇමරිකානු තැටිය (North American Plate)", "අප්‍රිකානු මහාද්වීපික තැටිය (African Plate)",
        "ශ්‍රී ලංකාව තැටි මායිමකින් දුරස්ව තැටි අභ්‍යන්තරයේ පිහිටි බැවින් සක්‍රීය ගිනිකඳු හා දරුණු දේශීය භූමිකම්පා අවමය."),
      q(t, "මුහුදු පතුලේ සිදුවන 'උණුසුම් ලක්ෂ්‍ය' (Hotspot) ගිනිකඳු ක්‍රියාකාරිත්වයේදී භූ තැටිය චලනය වන විට නිර්මාණය වන්නේ කුමක්ද?",
        "වයසින් වැඩි සිට ලාබාලම දූපත දක්වා පෙළ ගැසුණු ගිනිකඳු දූපත් දාමයක්", "මහාද්වීපයක් දෙකඩ වී ඇති වන දිගු විභේද නිම්නයක්", "මහාද්වීපික තැටි දෙකක් ගැටීමෙන් බිහිවන නැමි කඳු වැටියක්", "සාගරික තැටිය ගිලා බැසීමෙන් සෑදෙන ගැඹුරු සාගර අගාධයක්",
        "මැග්මා කුළුණ (Mantle Plume) ස්ථාවරව පවතින අතර ඊට උඩින් පැසිෆික් තැටිය ගමන් කිරීමෙන් නව දූපත් බිහිවේ."),
      q(t, "වැසි සමයේදී අධික ලෙස පස් කඩා වැටීම පාලනය කිරීම සඳහා කඳු බෑවුම්වල ගල් කැබලි කම්බි දැල්වලින් බැඳ ඉදිකරන ව්‍යුහය කුමක්ද?",
        "ගැබියන් බැමි (Gabion Walls)", "වැලි තුඩු හෙවත් ස්පිට් වැටි (Spits)", "තිරස් ආග්නේය සිල් තට්ටු (Sills)", "වෙරළබඩ කලපු බැමි (Lagoon Bars)",
        "ගැබියන් බැමි ජලයට පිටව යාමට ඉඩ සලසන බැවින් පිටුපසින් ජල පීඩනය රැඳී බිඳී යාම අඩු වේ."),
      q(t, "කාන්තාර ප්‍රදේශවල තාවකාලික ධාරානිපාත වැසි වලදී ජලය ගලා ගොස් පසුව වසරේ වැඩි කාලයක් වියළිව පවතින ගංගා නිම්නය කුමක්ද?",
        "වඩි නිම්නය (Wadi)", "ෆියෝඩ් නිම්නය (Fjord)", "මියැන්ඩර් වංගුව (Meander)", "වෙරළබඩ කලපුව (Lagoon)",
        "වියළි ගංගා පතුල්වල ජලය ඉක්මනින් වාෂ්ප වූ විට 'ප්ලායා' (Playa) නම් ලවණ තැනිතලා ඉතිරි වේ."),
      q(t, "කාන්තාරයේ සුළඟින් හැඩගැසුණු, දිගටි වැලි වැටි ලෙස සුළං දිශාවට සමාන්තරව කිලෝමීටර් ගණනක් විහිදෙන වැලි කඳු කුමක්ද?",
        "සීෆ් හෙවත් දිගටි වැලි කඳු (Seif Dunes)", "අඩසඳ හැඩැති බාචන් වැලි කඳු (Barchans)", "ග්ලැසියර ඩ්‍රම්ලින් කඳු ගැට (Drumlins)", "ගංගා ඉවුරු ස්වාභාවික ලෙවී වැටි (Levees)",
        "බාචන් වලට වෙනස්ව සීෆ් වැලි කඳු තියුණු තලයක් මෙන් දිගු තීරු ලෙස පවතී."),
      q(t, "කාන්තාරයේ දැඩි හා මෘදු පාෂාණ සිරස් තීරු ලෙස සුළඟට සමාන්තරව පිහිටි විට සුළං ඝර්ෂණයෙන් මෘදු කොටස් කැපී ඉතිරි වන පාෂාණ වැටි මොනවාද?",
        "යාර්ඩංස් වැටි (Yardangs)", "හිරිගල් ස්ටැලක්ටයිට් (Stalactites)", "ග්ලැසියර සර්ක් කුහර (Cirques)", "වෙරළබඩ වැලි කලපු (Lagoons)",
        "ඇල වූ පාෂාණ ස්තර තිරස්ව පිහිටි විට සෑදෙන ව්‍යුහය 'සියුගන්' (Zeugen) නම් වේ."),
      q(t, "ගංගාවක් ගමන් මාර්ගයේදී තම මුහුදු මට්ටම හදිසියේ පහළ බැසීම හෝ භූමිය ඉහළ යාම නිසා ගංගාව නැවත සිරස් ඛාදනය ආරම්භ කිරීම කුමක්ද?",
        "ගංගා පුනර්ජීවනය (Rejuvenation)", "මෝයකරණය (Estuarization)", "රසායනික ඔක්සිකරණය (Oxidation)", "හුණුගල් කාබනීකරණය (Carbonation)",
        "පුනර්ජීවනය නිසා ගංගා නිම්නවල 'ගංගා මාලු/සෝපාන' (River Terraces) සහ 'ගැඹුරු වූ මියැන්ඩර්' (Incised Meanders) සෑදේ."),
      q(t, "ගංගාවක ඉහළ කොටසේ සිරස් ඛාදනය නිසා ගංගාව දෙපස මාරුවෙන් මාරුවට ඉදිරියට නෙරා ඇති කඳු ගැට මොනවාද?",
        "අන්තර් බැඳි තුඩු (Interlocking Spurs)", "වෙරළබඩ මුහුදු තුඩු (Headlands)", "ගංගා ඉවුරු ලෙවී වැටි (Natural Levees)", "කාන්තාර බාචන් වැලි කඳු (Barchan Dunes)",
        "දිය පහර බාධක මගහැර වංගු ගසමින් ගලා යන නිසා පටු V-නිම්නයේදී Interlocking Spurs සෑදේ."),
      q(t, "ගංගාවක් ගං මෝයේදී රොන්මඩ තැන්පත් වී ප්‍රධාන ගංගාව කුඩා අතු බෙදී සාගරයට ගලා යන ඇළ මාර්ග හඳුන්වන්නේ කුමන නමකින්ද?",
        "විතරණිකා හෙවත් බෙදා හරින ඇළ (Distributaries)", "ඉහළ පෝෂක අතු ගංගා (Tributaries)", "සෝපානමය දිය ඇලි (Waterfalls)", "භූගත හුණුගල් සින්ක්හෝල් (Sinkholes)",
        "ඉහළ කොටසේ ජලය එකතු කරන්නේ Tributaries වන අතර ඩෙල්ටාවේදී ජලය බෙදා හරින්නේ Distributaries මගිනි."),
      q(t, "ගංගාවක් තම භාරය (Load) ප්‍රවාහනය කරන ප්‍රධාන ක්‍රම හතර මොනවාද?",
        "ද්‍රාවණය, අවලම්බනය, පැනීම සහ පතුලේ රූරා යාම", "වාෂ්පීකරණය, ඝනීභවනය, වර්ෂණය සහ ගැලීම", "ඔක්සිකරණය, කාබනීකරණය, ජල විච්ඡේදනය සහ ද්‍රාවණය", "හිම පැලීම, පතුරු ගැලවීම, උත්ස්වේදනය සහ ඛාදනය",
        "විශාල ගල් පතුලේ පෙරළී යාම Traction වන අතර සියුම් මැටි ජලයේ පාවී යාම Suspension වේ."),
      q(t, "ගංගාවක ශීර්ෂගාමී ඛාදනය (Headward Erosion) හේතුවෙන් එක් ගංගාවක් විසින් අසල්වැසි ගංගාවක ඉහළ ජල ප්‍රවාහය තමා වෙත හරවා ගැනීම කුමක්ද?",
        "ගංගා අල්ලා ගැනීම (River Capture)", "ඔක්ස්බෝ විල් සෑදීම (Oxbow Formation)", "මෝය ඩෙල්ටා නිර්මාණය (Delta Building)", "ගංවතුර පිටාර ගැලීම (Floodplain Overflow)",
        "ජලය අහිමි වූ පහළ ගංගා කොටස 'අනාථ ගංගාව' (Misfit Stream) ලෙසත් හැරවුණු ස්ථානය 'Elbow of Capture' ලෙසත් හැඳින්වේ."),
      q(t, "අභ්‍යන්තර පාෂාණ විද්‍යාවේදී පොළොව යට විශාලතම ගෝලාකාර හෝ අක්‍රමවත් ආග්නේය මැග්මා ආක්‍රමණය හඳුන්වන්නේ කෙසේද?",
        "බැතොලිත් (Batholith)", "ඩයික් (Dyke)", "සිල් (Sill)", "ලැකොලිත් (Laccolith)",
        "කාලයත් සමඟ මතුපිට පස ඛාදනය වූ පසු Batholith විශාල ග්‍රැනයිට් කඳුකර ලෙස මතුපිටට නිරාවරණය වේ."),
      q(t, "මැග්මා පාෂාණ ස්තර අතරට ඇතුළු වී ඉහළ ස්තර උඩට තල්ලු කර හතු හෝ ගෝලාකාර ආරුක්කු හැඩයෙන් ඝන වීම කුමක්ද?",
        "ලැකොලිත් (Laccolith)", "තිරස් සිල් (Sill)", "සිරස් ඩයික් (Dyke)", "මුදුන් කැල්ඩේරා (Caldera)",
        "ඇමරිකාවේ යූටා ප්‍රාන්තයේ Henry Mountains ලැකොලිත් ආක්‍රමණ සඳහා ප්‍රසිද්ධය."),
      q(t, "ලාවා වර්ග අතරින් ඉහළ සිලිකා ප්‍රතිශතයක් හා අධික දුස්ස්‍රාවිතාවක් (Viscosity) ඇති ලාවා කුමන බලපෑමක් ඇති කරයිද?",
        "වායු සිරවී ඉතා ප්‍රචණ්ඩ පිපිරුම්කාරී ගිනිකඳු විදාරණ ඇති කිරීම", "ඉතා සන්සුන්ව පැතලි තැනිතලා මත සැතපුම් ගණන් ගලා යාම", "සාගර පතුලේ කැල්සියම් කාබනේට් කොරල්පර නිර්මාණය කිරීම", "ධ්‍රැව කලාපවල ස්ථිර ග්ලැසියර අයිස් තට්ටු නිර්මාණය කිරීම",
        "සිලිකා අඩු බැසෝල්ට් ලාවා (Basic/Mafic) සිහින් බැවින් වායු පහසුවෙන් පිටවී සන්සුන්ව ගලා යයි."),
      q(t, "ගිනිකඳු පිපිරීමකදී උණුසුම් වායු, අළු සහ ගල් කැබලි අධික වේගයෙන් කන්ද පහළට ගලා යන අතිශය මාරාන්තික ධාරාව කුමක්ද?",
        "පයිරොක්ලාස්ටික් ප්‍රවාහය (Pyroclastic Flow)", "ද්‍රවශීලී ලාවා තටාකය (Lava Lake)", "භූතාපජ උණු දිය ගීසරය (Geyser)", "කඳුකර හිම කුණාටුව (Avalanche)",
        "ක්‍රි.ව. 79 දී පොම්පේ නගරය විනාශ කළ වෙසුවියස් විදාරණය මෙවැනි පයිරොක්ලාස්ටික් ප්‍රවාහයකි."),
      q(t, "ගිනිකඳු අළු හා ජලය (හිම දියවීමෙන් හෝ වැස්සෙන්) මිශ්‍ර වී ගිනිකඳු බෑවුම් දිගේ ගංගා නිම්න හරහා ගලන මඩ ගංවතුර කුමක්ද?",
        "ලාහාර් හෙවත් ගිනිකඳු මඩ ගැලීම (Lahar)", "භූ කම්පන සීස්මොග්‍රෑම් සටහන (Seismogram)", "කඳු පාමුල ටැලස් බෑවුම (Talus Slope)", "සුළං තැන්පතු ලොයෙස් පස (Loess)",
        "1985 දී කොලොම්බියාවේ නෙවාඩෝ ඩෙල් රුයිස් විදාරණයෙන් ඇතිවූ ලාහාර් ප්‍රවාහයෙන් ආර්මේරෝ නගරය යට විය."),
      q(t, "ගිනිකඳු ආශ්‍රිත කලාපවල අධික අවදානමක් පැවතියද මිනිසුන් ඒ අවට ඝනව පදිංචි වීමට ප්‍රධාන භූගෝලීය හේතුව කුමක්ද?",
        "ගිනිකඳු අළු හා ලාවා ජීර්ණයෙන් සෑදෙන පස ඉතා සාරවත් වීම සහ භූතාපජ ශක්තිය හා ඛනිජ ලැබීම", "එම ප්‍රදේශවල වසර පුරාම අධික වළාකුළු පැවතීම නිසා හිරු එළිය නොමැති වීම", "ගිනිකඳු කඳු වැටි අවට සම්පූර්ණයෙන්ම වියළි කාන්තාර පරිසරයක් පමණක් පැවතීම", "උෂ්ණත්වය අධික වීම නිසා කිසිදු කෘෂිකාර්මික පළිබෝධකයෙකු එම කලාපයේ නොසිටීම",
        "ඉන්දුනීසියාවේ ජාවා දූපත හා ඉතාලියේ නේපල්ස් ප්‍රදේශය මීට ප්‍රකට උදාහරණ වේ."),
      q(t, "භූමිකම්පාවකදී පාෂාණ ස්තර හරහා සම්පීඩන තරංග ලෙස වේගයෙන්ම භූ කම්පන මානයට ළඟා වන තරංග මොනවාද?",
        "ප්‍රාථමික තරංග (P-Waves)", "ද්විතීයික තරංග (S-Waves)", "රේලි පෘෂ්ඨීය තරංග (Rayleigh Waves)", "ලව් පෘෂ්ඨීය තරංග (Love Waves)",
        "P තරංග ඝන, ද්‍රව හා වායු යන මාධ්‍ය තුනම හරහා ගමන් කළ හැකිය."),
      q(t, "විශාල භූමිකම්පාවක් සිදුවූ ස්ථානයක අපිකේන්ද්‍රය (Epicenter) නිවැරදිව සොයා ගැනීම සඳහා අවම වශයෙන් භූ කම්පන මධ්‍යස්ථාන කීයක දත්ත අවශ්‍යද?",
        "භූ කම්පන මධ්‍යස්ථාන 3 ක දත්ත", "භූ කම්පන මධ්‍යස්ථාන 1 ක දත්ත", "භූ කම්පන මධ්‍යස්ථාන 10 ක දත්ත", "භූ කම්පන මධ්‍යස්ථාන 50 ක දත්ත",
        "එක් එක් මධ්‍යස්ථානයේ P හා S තරංග පැමිණීමේ කාල වෙනසින් දුර සොයා වෘත්ත තුනක් කැපෙන ලක්ෂ්‍යය ගනු ලැබේ."),
      q(t, "වැලි සහිත ජල සංතෘප්ත පොළොවක් ප්‍රබල භූමිකම්පාවකදී සෙලවීම නිසා එහි ඝන ශක්තිය අහිමි වී මඩ ද්‍රවයක් මෙන් හැසිරී ගොඩනැගිලි ගිලා බැසීම කුමක්ද?",
        "පාංශු ද්‍රවීකරණය (Soil Liquefaction)", "රසායනික කාබනීකරණය (Carbonation)", "මන්දගාමී පාංශු රූරා යාම (Soil Creep)", "තාප පතුරු ගැලවීම (Exfoliation)",
        "1964 නිගාටා (ජපානය) හා 2011 ක්‍රයිස්ට්චර්ච් භූමිකම්පාවලදී Liquefaction දරුණු හානි කළේය."),
      q(t, "ලෝකයේ ප්‍රධාන පාෂාණ කාණ්ඩ අතර පෘථිවි කබොලේ මතුපිටින් 75% කට ආසන්න ප්‍රදේශයක් ආවරණය කර ඇති පාෂාණ කාණ්ඩය කුමක්ද?",
        "අවසාදිත පාෂාණ (Sedimentary Rocks)", "ආග්නේය පාෂාණ (Igneous Rocks)", "විපරීත පාෂාණ (Metamorphic Rocks)", "මැග්මා පාෂාණ (Magmatic Rocks)",
        "මුළු කබොලේ පරිමාවෙන් 95% ක් ආග්නේය හා විපරීත වුවද, මතුපිට පෘෂ්ඨයේ වැඩි කොටසක් අවසාදිත ස්තර වේ."),
      q(t, "ශ්‍රී ලංකාවේ මුහුදු බඩ තීරයේ දක්නට ලැබෙන, ලංකාවේ භූමි ඉතිහාසයේ ලාබාලතම අවසාදිත පාෂාණ විශේෂය කුමක්ද?",
        "මයෝසීන හුණුගල් (Miocene Limestone)", "ප්‍රාග්-කේම්බ්‍රියානු ග්‍රැනයිට් (Granite)", "ජුරාසික වැලිගල් (Jurassic Sandstone)", "අභ්‍යන්තර බැසෝල්ට් ලාවා (Basalt)",
        "අරුවක්කාලු හා කන්කසන්තුරේ සිමෙන්ති කර්මාන්ත සඳහා මෙම මයෝසීන හුණුගල් උපයෝගී කර ගනී."),
      q(t, "භූ විද්‍යාත්මකව ශ්‍රී ලංකාවේ වයඹ දිග පුත්තලමේ සිට යාපනය දක්වා පිහිටි මයෝසීන හුණුගල් ස්තරවල ප්‍රධාන ජල විද්‍යාත්මක වැදගත්කම කුමක්ද?",
        "විශිෂ්ට භූගත ජලධර සාදා යාපනය අර්ධද්වීපයේ කෘෂිකර්මයට ජලය සැපයීම", "වයඹ දිග වෙරළ තීරයේ සක්‍රීය භූතාපජ ගිනිකඳු නිර්මාණය කිරීම", "මුහුදු පතුලේ රන් හා යකඩ ලෝහ නිධි බහුලව තැන්පත් කිරීම", "වෙරළබඩ කඩොලාන පරිසර පද්ධති සම්පූර්ණයෙන්ම විනාශ කර දැමීම",
        "යාපනයේ ගොවිතැන හා පානීය ජලය ප්‍රධාන වශයෙන්ම හුණුගල් භූගත ජලධර මත රඳා පවතී."),
      q(t, "ගංගා ඛාදනය හා සම්බන්ධ 'ඩේවිස්ගේ ඛාදන චක්‍රයේ' (Cycle of Erosion) අවධි තුන කවරේද?",
        "තරුණ අවධිය, මේරූ අවධිය සහ මහලු අවධිය", "ගිම්හාන අවධිය, ශීත අවධිය සහ සරත් අවධිය", "ආග්නේය අවධිය, අවසාදිත අවධිය සහ විපරීත අවධිය", "නාභි අවධිය, අපිකේන්ද්‍ර අවධිය සහ සුනාමි අවධිය",
        "මහලු අවධියේදී මුළු භූමියම සමතලා වී ඉතිරි වන පැතලි තැන්න 'පෙනිප්ලේන්' (Peneplain) නම් වේ."),
      q(t, "පැතලි සමතලා තැන්නක (Peneplain) ඛාදනයට ප්‍රතිරෝධී වී තනිව ඉහළට නැගී සිටින සීගිරිය වැනි පාෂාණ කඳු ගැට හඳුන්වන්නේ කුමන නමකින්ද?",
        "අවශේෂ කඳු හෙවත් ඉන්සෙල්බර්ග් (Inselberg)", "භූ තැටි නැමි කඳු (Fold Mountains)", "ද්‍රවශීලී පළිහ ගිනි කඳු (Shield Volcanoes)", "ග්ලැසියර සර්ක් කඳු (Cirque Peaks)",
        "සීගිරිය, දඹුල්ල හා දිඹුලාගල වැනි පාෂාණ පර්වත දැඩි විපරීත පාෂාණ ඛාදනයෙන් ඉතිරි වූ අවශේෂ කඳු වේ."),
      q(t, "ගංගාවක් ගමන් ගන්නා මාර්ගයේ ඇති වන අවසන් පහළම ඛාදන සීමාව ('Ultimate Base Level of Erosion') ලෙස සැලකෙන්නේ කුමක්ද?",
        "සාගර මට්ටම හෙවත් මුහුදු මට්ටම (Sea Level)", "කඳුකර ජල පෝෂක මුදුන (Mountain Summit)", "මධ්‍ය නිම්නයේ ගංගා ඉවුර (River Bank)", "භූගත මැග්මා කුටිය (Magma Chamber)",
        "ගංගාවකට සාමාන්‍යයෙන් සාගර මට්ටමට වඩා ගැඹුරට භූමිය ඛාදනය කළ නොහැක."),
      q(t, "භූ තැටි සීමාවල නව සාගරික කබොල නිරන්තරයෙන් නිර්මාණය වන ප්‍රධාන සාගර පද්ධතිය කුමක්ද?",
        "මධ්‍ය අත්ලාන්තික් වැටිය (Mid-Atlantic Ridge)", "පැසිෆික් මරියානා අගාධය (Mariana Trench)", "මැදපෙරදිග පර්සියානු බොක්ක (Persian Gulf)", "ලෝහිත මුහුදේ දකුණු මෝය (Bab-el-Mandeb)",
        "මෙම වැටිය අයිස්ලන්තය හරහා ගොඩබිම මතින්ද ගමන් කරන බැවින් අයිස්ලන්තයේ ගිනිකඳු හා උණු දිය උල්පත් බහුලය."),
      q(t, "රතු මුහුද (Red Sea) හා නැගෙනහිර අප්‍රිකානු විභේද නිම්නය (East African Rift Valley) අනාගතයේදී කුමක් බවට පත්වීමේ භූ විද්‍යාත්මක ප්‍රවණතාවක් පවතීද?",
        "අප්‍රිකානු මහාද්වීපය දෙකඩ වී නව සාගර ද්‍රෝණියක් බිහිවීම", "හිමාලය මෙන් උස් නැමි කඳු වැටියක් බවට පත්වීම", "අයිස් තට්ටුවකින් වැසී ස්ථිර ග්ලැසියරයක් බවට පත්වීම", "දෙපස භූ තැටි ගැටී සම්පූර්ණයෙන්ම වැසී ගොඩබිමක් වීම",
        "සෝමාලි තැටිය නූබියන් තැටියෙන් ඈත් වීම මීට වසර මිලියන ගණනක් පුරා සිදුවෙමින් පවතී."),
      q(t, "ගොඩබිම් මතුපිට ඇති සාරවත් පස කාලගුණය, භූ විෂමතාව, මව් පාෂාණය, ජීවීන් හා කාලය යන සාධක පහ මත සෑදීම හඳුන්වන්නේ කුමක් ලෙසද?",
        "පාංශු ජනනය (Pedogenesis)", "රසායනික පාෂාණ දියවීම (Solution)", "සමුද්‍ර වෙරළ ඛාදනය (Coastal Erosion)", "අවසාදිත මෝය සාදනය (Estuarine Silting)",
        "එකම මව් පාෂාණයකින් වුවද තෙත් කලාපයේ සහ වියළි කලාපයේ සෑදෙන පස් වර්ග දේශගුණය නිසා වෙනස් වේ."),
      q(t, "ශ්‍රී ලංකාවේ තෙත් කලාපයේ රබර්, තේ සහ කුරුඳු වගා සඳහා බහුලව භාවිත වන ප්‍රධාන පස් වර්ගය කුමක්ද?",
        "රතු-කහ පොඩ්සොලික් පස (Red-Yellow Podzolic)", "රතු දුඹුරු පස (Reddish Brown Earths)", "වෙරළබඩ රෙගුසෝල් වැලි පස (Regosols)", "ක්ෂාරීය හා ලවණ පස (Saline Soils)",
        "වියළි කලාපයේ වඩාත් ප්‍රචලිත වගා පස වන්නේ 'රතු දුඹුරු පස' (Reddish Brown Earths - RBE) ය."),
      q(t, "ශ්‍රී ලංකාවේ වෙරළබඩ තීරයේ කලපු අවට හා වෙරළ තීරයේ පොල් වගාව සඳහා බහුලව හමුවන වැලිමය පස් වර්ගය කුමක්ද?",
        "රෙගුසෝල් සහ ක්ෂාරීය වැලි පස්", "සෞම්‍ය කළු චර්නොසෙම් පස්", "ධ්‍රැවීය ටුන්ඩ්‍රා පීට් පස්", "සුළං තැන්පතු ලොයෙස් පස්",
        "පහතරට ගංගා නිම්නවල වී වගාව සඳහා 'දියළු පස' (Alluvial Soil) ඉතා සාරවත් ලෙස පවතී."),
      q(t, "සාගර පතුලේ ප්‍රධාන භූ ලක්ෂණ අතර වෙරළේ සිට මුහුද දෙසට මීටර් 200 ක් පමණ ගැඹුරකට මෘදු බෑවුමකින් විහිදෙන සාගර ප්‍රදේශය කුමක්ද?",
        "මහද්වීපික තටාකය (Continental Shelf)", "මහද්වීපික බෑවුම (Continental Slope)", "ගැඹුරු සාගර අගාධය (Ocean Trench)", "සාගර අගාධ තැනිතලාව (Abyssal Plain)",
        "ලෝකයේ ප්‍රධාන මත්ස්‍ය සම්පත සහ අක්වෙරළ ඛනිජ තෙල්/ගෑස් නිධි බහුලව පවතින්නේ Continental Shelf තුළය."),
      q(t, "සාගරයේ මීටර් 3,000 සිට 6,000 දක්වා ගැඹුරේ පිහිටි, පෘථිවියේ සමතලාම හා විශාලතම ප්‍රදේශය ලෙස සැලකෙන සාගර පතුල කුමක්ද?",
        "අගාධ තැනිතලාව (Abyssal Plain)", "මහද්වීපික තටාකය (Continental Shelf)", "නොගැඹුරු කොරල්පරය (Coral Reef)", "ගංගා මෝය ඩෙල්ටාව (River Delta)",
        "ගොඩබිමෙන් හා සාගර ජීවීන්ගෙන් පතිත වන සියුම් අවසාදිත මගින් මෙම පතුල ආවරණය වී ඇත."),
      q(t, "භූමියේ බෑවුම්වල 'හෙල්මළු වගාව' (Terracing) සහ 'සමෝච්ච බැමි' යෙදීමේ ප්‍රධාන භූගෝලීය අරමුණ කුමක්ද?",
        "වැසි ජලයේ වේගය අඩු කර පසට ජලය උරා ගැනීම වැඩි කිරීම හා පාංශු ඛාදනය වැළැක්වීම", "කඳු බෑවුම් හරහා හමන සුළඟේ වේගය වැඩි කර වාෂ්පීකරණය ඉහළ දැමීම", "සාගරයේ වඩදිය ජලය කඳුකර වගා බිම් වෙත පහසුවෙන් ගෙන ඒමට සැලැස්වීම", "භූගත පාෂාණ ස්තර පුපුරුවා හැර ඛනිජ සම්පත් පොළොව මතුපිටට ගැනීම",
        "පිලිපීනයේ ඉෆුගාඕ හෙල්මළු හා ශ්‍රී ලංකාවේ කඳුකර හෙල්මළු කුඹුරු මීට විශිෂ්ට උදාහරණ වේ."),
      q(t, "මුහුදු වෙරළේ තරංග ඛාදනය නිසා තුඩුවක (Headland) දෙපස පාදමේ ඇති වන අවපාත සහ ගැඹුරු කුහර පිළිවෙළින් කුමක්ද?",
        "තරංග කැපුම් කට්ටය සහ මුහුදු ගුහා", "වැලි තුඩුව සහ බාධක වැලි වැටිය", "ගංගා ඩෙල්ටාව සහ ස්වාභාවික ලෙවී වැටිය", "කාන්තාර බාචන් සහ සීෆ් වැලි කඳු",
        "කාලයත් සමඟ Notch ගැඹුරු වී ඉහළ පාෂාණ කඩා වැටීමෙන් මුහුදු ප්‍රපාතය පසුබසී."),
      q(t, "ගංගා මෝයක ලවණ හා මිරිදිය ජලය මිශ්‍ර වීමෙන් ඉතා සියුම් මැටි අංශු එකට ඇලී බර වී පතුලට බැස ඩෙල්ටා සෑදීමට උපකාර වන ක්‍රියාවලිය කුමක්ද?",
        "කැටි ගැසීම හෙවත් ෆ්ලොක්‍යුලේෂන් (Flocculation)", "තාප පතුරු ගැලවීම (Thermal Exfoliation)", "භූ තැටි යටි ගිලා බැසීම (Subduction)", "ශීත කඳුකර තුහින පැලීම (Frost Shattering)",
        "සාගර ලවණ අයන සියුම් මැටි අංශුවල ආරෝපණ උදාසීන කර ඒවා එකට එක් කර තැන්පත් කරයි."),
      q(t, "භූ තැටි විද්‍යාවේදී 'නිෂ්ක්‍රීය මහාද්වීපික මායිමක්' (Passive Margin) සඳහා නිවැරදි ලක්ෂණය හා උදාහරණය කුමක්ද?",
        "භූ කම්පන හා ගිනිකඳු විරල, මහාද්වීපික තටාකය පුළුල් වූ අත්ලාන්තික් වෙරළ තීරය", "ගැඹුරු සාගර අගාධ හා දරුණු භූ කම්පන බහුල මරියානා අගාධ තීරය", "සක්‍රීය ගිනිකඳු පිපිරීම් 75% ක් පමණ සිදුවන පැසිෆික් ගිනි වළල්ල", "මහාද්වීපික තැටි දෙකක් ගැටීමෙන් බිහිවූ හිමාලය කඳුකර කලාපය",
        "එක්සත් ජනපදයේ නැගෙනහිර වෙරළ නිෂ්ක්‍රීය මායිමක් වන අතර බටහිර වෙරළ සක්‍රීය තැටි මායිමකි."),
      q(t, "පොළොව යට ඇති උණුසුම් මැග්මා හෝ ජලතාපක ධාරා මගින් රන්, තඹ හා රිදී වැනි ලෝහමය ඛනිජ පාෂාණ පැලුම් තුළ තැන්පත් වී සෑදෙන්නේ කුමක්ද?",
        "ඛනිජ නහර හෙවත් ලෝඩ් නිධි (Mineral Veins)", "ගංගා මෝය අවසාදිත ස්තර (Sedimentary Beds)", "කාබනික පොසිල ඉන්ධන නිධි (Fossil Fuels)", "නොගැඹුරු කැල්සියම් කොරල්පර (Coral Reefs)",
        "අධික පීඩනය යටතේ උණුසුම් ඛනිජ ද්‍රාවණ සිසිල් වන විට මෙම වටිනා ලෝහ නිධි නිර්මාණය වේ."),
      q(t, "රළු භූ විෂමතාවක් පවතින කඳුකර ප්‍රදේශවල විශාල කළුගල් කුට්ටි නිරාවරණය වී තිබෙන විට දක්නට ලැබෙන 'ටෝර්' (Tor) භූ රූපය සෑදෙන්නේ කෙසේද?",
        "භූගත රසායනික ජීර්ණයෙන් සන්ධි හරහා පාෂාණය බිඳී ගොස් පසුව මතුපිට ජීර්ණ පස් සේදී යාමෙන්", "සාගර පතුලේ භූමිකම්පා නිසා ඇතිවන දැවැන්ත සුනාමි රළ ගොඩබිමට වැදීමෙන්", "ධ්‍රැව කලාපවලින් පැමිණෙන විශාල හිම කඳු එකිනෙකට තදින් ගැටී කැඩී යාමෙන්", "අභ්‍යවකාශයේ සිට පෘථිවි පෘෂ්ඨයට කඩා වැටෙන විශාල උල්කාපාතවල බලපෑමෙන්",
        "දකුණු බටහිර එංගලන්තයේ ඩාට්මූර් (Dartmoor) හා ශ්‍රී ලංකාවේ ඇතැම් කඳු ගැටවල මෙම ගල් කුළුණු දැකිය හැක."),
      q(t, "ඉතා ගැඹුරු සිරස් බෑවුම් සහිතව ගංගාවක් මගින් පාෂාණ කැපී සෑදෙන දිගු පටු නිම්නයක් (උදා: ග්‍රෑන්ඩ් කැන්යොන්) හඳුන්වන්නේ කුමක් ලෙසද?",
        "කැන්යොන් හෙවත් මහා ගිරිදුර්ගය (Canyon)", "ගංගා මෝය ඩෙල්ටාව (River Delta)", "වෙරළබඩ නොගැඹුරු කලපුව (Lagoon)", "ග්ලැසියර මොරේන් වැටිය (Moraine)",
        "ශුෂ්ක හෝ අර්ධ ශුෂ්ක සානු ප්‍රදේශවල කොලරාඩෝ වැනි ගංගා ගලා යන විට ගැඹුරු කැන්යොන් නිර්මාණය වේ."),
      q(t, "මුහුදු මට්ටම ඉහළ යාම හේතුවෙන් පැරණි ගංගා නිම්න මුහුදු ජලයෙන් යටවී සෑදෙන අතු බෙදුණු ගැඹුරු බොක්ක සහිත වෙරළ තීරය කුමක්ද?",
        "රියා වෙරළ (Ria Coast)", "ඩැල්මේෂියන් වෙරළ (Dalmatian Coast)", "ඇටෝල් කොරල් වෙරළ (Atoll Coast)", "ලොයෙස් තැන්න වෙරළ (Loess Coast)",
        "ග්ලැසියර නිම්න ගිලී යාමෙන් ෆියෝඩ් සෑදෙන අතර ගංගා නිම්න ගිලී යාමෙන් රියා (Ria) වෙරළ සෑදේ."),
      q(t, "භූ තැටි සීමාවන්හිදී පෘථිවි කබොලේ කොටසක් පීඩනය නිසා නැමීමෙන් සෑදෙන 'නැමි කන්දක' ඉහළට නෙරා ගිය කොටස හා පහළට නැමුණු කොටස කුමක්ද?",
        "ප්‍රතිනැමිය (Anticline) සහ අනුනැමිය (Syncline)", "හෝස්ට් කන්ද (Horst) සහ ග්‍රාබන් නිම්නය (Graben)", "සිරස් ඩයික් (Dyke) සහ තිරස් සිල් (Sill)", "ස්ටැලක්ටයිට් (Stalactite) සහ ස්ටැලග්මයිට් (Stalagmite)",
        "පිළිවෙළින් කඳු වැටි මුදුන් Anticline ලෙසත් නිම්න Syncline ලෙසත් හඳුනා ගනී."),
      q(t, "ආග්නේය පාෂාණ අතර ඉතා සැහැල්ලු හා වායු බුබුළු බහුල බැවින් ජලයේ පාවිය හැකි ස්වාභාවික පාෂාණ විශේෂය කුමක්ද?",
        "පියුමිස් හෙවත් පෙන ගල් (Pumice)", "අභ්‍යන්තර ග්‍රැනයිට් (Granite)", "විපරීත කිරිගරුඬ (Marble)", "බාහිර බැසෝල්ට් (Basalt)",
        "වායු බහුල ලාවා ක්ෂණිකව සිසිල් වීමේදී වායු බුබුළු සිරවී Pumice නිර්මාණය වේ."),
      q(t, "ගිනිකඳු විදාරණයකදී සිලිකා බහුල ලාවා ස්ඵටික සෑදීමට පවා කාලය නොමැතිව ක්ෂණිකව සිසිල් වී සෑදෙන ස්වාභාවික ගිනිකඳු වීදුරුව කුමක්ද?",
        "ඔබ්සිඩියන් (Obsidian)", "ක්වාර්ට්ස් (Quartz)", "ස්ලේට් (Slate)", "හුණුගල් (Limestone)",
        "අතීත මානවයන් තියුණු ආයුධ සෑදීම සඳහා කළු පැහැති Obsidian භාවිත කර ඇත."),
      q(t, "ගල් අඟුරු සෑදීමේදී ශාක අවශේෂ පීට්, ලිග්නයිට්, බිටුමිනස් හරහා අවසානයේ ඉහළම කාබන් ප්‍රතිශතයක් ඇති ගල් අඟුරු වර්ගය බවට පත්වේ. එය කුමක්ද?",
        "ඇන්ත්‍රසයිට් (Anthracite)", "පීට් (Peat)", "ලිග්නයිට් (Lignite)", "ශේල් (Shale)",
        "Anthracite 90% කට වඩා කාබන් අඩංගු ඉහළම තාප ශක්තිය ලබා දෙන ගල් අඟුරු වර්ගයයි."),
      q(t, "ජලය හෝ සුළඟ මගින් තැන්පත් කරන ලද සිනිඳු පස් හා ගල් කැබලි සම්පීඩනය වී රසායනිකව එකට බැඳී පාෂාණයක් බවට පත්වීමේ ක්‍රියාවලිය කුමක්ද?",
        "ලිතිෆිකරණය හෙවත් ශිලාභවනය (Lithification)", "රසායනික ඔක්සිකරණය (Chemical Oxidation)", "භූ තැටි යටි ගිලා බැසීම (Subduction)", "භෞතික පාෂාණ ජීර්ණය (Physical Weathering)",
        "සම්පීඩනය (Compaction) සහ බැඳීම (Cementation) යන පියවර දෙක Lithification සම්පූර්ණ කරයි."),
      q(t, "පැරණි නැමි කඳු වැටි (උදා: ඇපලේචියන්, යූරල්) හිමාලයට වඩා උසින් අඩු හා රවුම් මුදුන් සහිත වන්නේ ඇයි?",
        "වසර මිලියන සිය ගණනක් පුරා ඛාදනයට හා ජීර්ණයට ලක්වී ක්ෂය වී ඇති බැවින්", "එම කඳු වැටි පිහිටි ප්‍රදේශ සම්පූර්ණයෙන්ම වියළි කාන්තාර බවට පත්ව ඇති බැවින්", "එම කඳු මුදුන් මත නිරන්තරයෙන් සක්‍රීය ගිනිකඳු පිපිරීම් සිදුවී පහත් වී ඇති බැවින්", "ඒවා ධ්‍රැව කලාපවලින් ඈත්ව පිහිටි බැවින් කඳු මුදුන් මත හිම තට්ටු නොමැති නිසා",
        "හිමාලය, ඇල්ප්ස්, රොකී හා ඇන්ඩීස් උල් මුදුන් සහිත තරුණ නැමි කඳු (Young Fold Mountains) වේ."),
      q(t, "ජල වහන රටා (Drainage Patterns) අතර එක් මධ්‍ය උස් ගිනිකඳු කේතුවකින් හෝ කඳු මුදුනකින් සෑම දිශාවටම ගංගා ගලා යන රටාව කුමක්ද?",
        "අරීය ජල වහන රටාව (Radial Pattern)", "වෘක්ෂාකාර ජල වහන රටාව (Dendritic Pattern)", "සමාන්තර ජල වහන රටාව (Parallel Pattern)", "ජාලාකාර ජල වහන රටාව (Trellis Pattern)",
        "ශ්‍රී ලංකාවේ සමනල කඳු වැටිය (Sri Pada) ආශ්‍රිතව මධ්‍යම කඳුකරයෙන් ගංගා සතර දිශාවට ගැලීම අරීය රටාවකි."),
      q(t, "ගසක අතු බෙදී යන ආකාරයෙන් සමාකාර ප්‍රතිරෝධී පාෂාණ සහිත භූමියක ගොඩනැගෙන සුලබම ජල වහන රටාව කුමක්ද?",
        "අතු ගංගා උල් කෝණවලින් ප්‍රධාන ගංගාවට එක්වන වෘක්ෂාකාර ජල වහන රටාව", "කේන්ද්‍රීය කඳු මුදුනක සිට සතර දිශාවට විහිදෙන අරීය ජල වහන රටාව", "වළලු හැඩයෙන් පාෂාණ වැටි වටා ගලා යන වළයාකාර ජල වහන රටාව", "මධ්‍යම අවපාතයක් දෙසට ඇතුළට ගලා යන අභිසාරී ජල වහන රටාව",
        "අතු ගංගා උපරිම කාර්යක්ෂමතාවයෙන් ප්‍රධාන ගංගාවට උල් කෝණවලින් එක්වීම Dendritic රටාවේ ලක්ෂණයයි."),
      q(t, "දැඩි හා මෘදු පාෂාණ සමාන්තර තීරු ලෙස පිහිටි භූමියක අතු ගංගා ප්‍රධාන ගංගාවට සෘජුකෝණීව (90°) එකතු වන ජල වහන රටාව කුමක්ද?",
        "සමාන්තර කඳු වැටි හා නිම්න අතර බිහිවන ජාලාකාර ජල වහන රටාව", "උස් ගිනිකඳු කේතුවකින් පහළට විහිදෙන අරීය ජල වහන රටාව", "සමතලා දියළු තැන්නක ගසක අතු මෙන් පැතිරෙන වෘක්ෂාකාර රටාව", "හුණුගල් භූමියක පොළොව යටට කිඳා බසින භූගත ජල වහන රටාව",
        "ශ්‍රී ලංකාවේ නිරිතදිග සමාන්තර වැටි හා නිම්න (Ridge and Valley) කලාපයේ Trellis ජල වහනය දැකිය හැක."),
      q(t, "ලංකාවේ පවතින පැරණි භූ විද්‍යාත්මක 'විජයානු සංකීර්ණය', 'හයිලන්ඩ් සංකීර්ණය' හා 'වන්නි සංකීර්ණය' ප්‍රධාන වශයෙන් කුමන පාෂාණ කාණ්ඩයට අයත්ද?",
        "අධික තාපය හා පීඩනය යටතේ සැකසුණු ප්‍රාග්-කේම්බ්‍රියානු විපරීත පාෂාණ", "ගිනිකඳු පිපිරීම්වලින් ඉහළට ගලා සිසිල් වූ නව ආග්නේය බැසෝල්ට් පාෂාණ", "උතුරු මුහුදු තීරයේ තැන්පත් වූ මයෝසීන යුගයේ අවසාදිත හුණුගල්", "ගංගා මෝය ආශ්‍රිතව මෑතකදී ඝන වූ කොරල් හා වැලිගල් තට්ටු",
        "ලෝක ප්‍රකට ශ්‍රී ලංකා මැණික් නිධි බහුලව සෑදී ඇත්තේ හයිලන්ඩ් සංකීර්ණයේ විපරීත පාෂාණ ආශ්‍රිතවය."),
      q(t, "භූගත ජල ක්‍රියාකාරිත්වයේදී පාෂාණ ස්තර අතර පීඩනය යටතේ සිරවූ ජලය ළිඳක් හෑරූ විට පොම්ප නොකර ඉබේම ඉහළට විදින ළිං වර්ගය කුමක්ද?",
        "ආටීසියානු ළිඳ (Artesian Well)", "ගැඹුරු පොම්ප නළ ළිඳ (Tube Well)", "භූතාපජ උණු ජල ගීසරය (Geyser)", "හුණුගල් ගිලා බැසීමේ සින්ක්හෝල්",
        "ඕස්ට්‍රේලියාවේ මහා ආටීසියානු ද්‍රෝණිය (Great Artesian Basin) ලොව විශාලතම ආටීසියානු ජල පද්ධතියයි."),
      q(t, "ලෝකයේ ස්වාභාවික භූ තල කඩා වැටීම් අතර 'පාෂාණ ඇද වැටීම' (Rockfall) වැඩිපුරම සිදු වන්නේ කුමන බෑවුම්වලද?",
        "ඉතා තියුණු සිරස් පාෂාණ ප්‍රපාත සහ සන්ධි බහුල කඳු බෑවුම්වල", "සමතලා ගංගා පිටාර තැනිතලා හා වගුරු බිම් ආශ්‍රිත පහත් බිම්වල", "මුහුදු රළින් තැන්පත් වූ මෘදු වැලි වෙරළ තීර හා වැලි කඳු පාමුල", "මෘදු මැටි පස් ස්තර ඇති අඩු ආනති ගොවිබිම් හා නිම්නවල",
        "තුහින පැලීම, මූල ක්‍රියාව හෝ භූ කම්පන නිසා ගල් කුට්ටි ගැලවී කෙළින්ම පහළට වැටේ."),
      q(t, "බෑවුමක පිහිටි ජලය උරා ගත් මැටි හෝ පස් ස්කන්ධයක් වක්‍රාකාර ලිස්සා යාමේ පෘෂ්ඨයක් ඔස්සේ කැරකී පහළට බැසීම කුමක්ද?",
        "වක්‍රාකාර පෘෂ්ඨයක් දිගේ සිදුවන භ්‍රමණ ලිස්සා යාම (Slumping)", "අවුරුදු ගණනක් පුරා ඉතා සෙමින් සිදුවන පාංශු රූරා යාම (Soil Creep)", "වියළි සුළඟින් සියුම් දූවිලි තැන්පත් වන ලොයෙස් තැන්පතුව", "මුහුදු රළ මගින් සැකසෙන වෙරළබඩ ඛාදන ගල් පුවරු කඩා වැටීම",
        "විශේෂයෙන් මෘදු මැටි වෙරළ ප්‍රපාත පාමුල මුහුදු රළින් කැපුණු විට Slumping සුලබව දැකිය හැක."),
      q(t, "වෙරළබඩ සුළඟ මගින් වියළි මුහුදු වැලි ගොඩබිම දෙසට ගසාගෙන විත් තණකොළ හා පඳුරු අතර රැඳීමෙන් නිර්මාණය වන භූ ලක්ෂණය කුමක්ද?",
        "වෙරළබඩ වැලි කඳු (කල්පිටිය හා හම්බන්තොට වැනි ප්‍රදේශ)", "ගැඹුරු ග්ලැසියර නිම්න මුහුදින් යටවූ ෆියෝඩ් බොකු", "උණුසුම් මුහුදේ කැල්සියම් සැකිලිවලින් වැඩෙන කොරල්පර", "ග්ලැසියර දියවීමෙන් නිම්න පාමුල රැඳෙන මොරේන් ගල් වැටි",
        "මෙම වැලි කඳු වෙරළ තීරයට ස්වාභාවික ආරක්ෂක පවුරක් ලෙස ක්‍රියා කර කුණාටු රළ වළකයි."),
      q(t, "මුහුදු කලපුවක් හෝ බොක්කක් හරහා එක් කෙළවරක සිට අනෙක් කෙළවර දක්වාම වැලි වැටියක් වැඩී බොක්ක මුහුදෙන් වෙන් කිරීමෙන් සෑදෙන්නේ කුමක්ද?",
        "වැලි බාධක වැටිය හෙවත් සෑන්ඩ් බාර් (Sand Bar)", "ග්ලැසියර ඛාදනයෙන් සැකසෙන කඳු අවපාතයක් වන සර්ක්", "පෘථිවි කබොලේ මැග්මා ඝන වීමෙන් සෑදෙන සිරස් ඩයික් වැටිය", "ශුෂ්ක සානුවක ගංගාවක් මගින් කැපුණු ගැඹුරු කැන්යොන් නිම්නය",
        "මඩකලපුව, පුත්තලම හා මීගමුව කලපු වැලි වැටි මගින් සාගරයෙන් අර්ධ වශයෙන් වෙන්වී ඇත."),
      q(t, "ගංගා මෝයක උදම් රළ වේගයෙන් ගංගාව ඇතුළට ගලා ඒමේදී ඇතිවන එකම උස ජල බිත්තියක් මෙන් ඉහළට යන තරංගය කුමක්ද?",
        "උදම් රළ ප්‍රවාහය හෙවත් ටයිඩල් බෝර් (Tidal Bore)", "සාගර පතුලේ භූමිකම්පාවකින් ඇතිවන විනාශකාරී සුනාමි රළ", "කඳුකර ග්ලැසියර ආරම්භයේ පවතින වළක් වැනි සර්ක් අවපාතය", "කාන්තාර පෙදෙස්වල වර්ෂාවෙන් පමණක් පිරෙන වියළි වඩි ඇළ",
        "පුනීල හැඩැති නොගැඹුරු මෝයවල මහා වඩදිය (Spring Tide) අවස්ථාවේදී Tidal Bore දැකිය හැක."),
      q(t, "කාන්තාර පරිසරවල සානුවක් ඛාදනය වී ඉතිරි වන පැතලි මුදුනක් හා තියුණු බෑවුම් සහිත විශාල ගල් කඳු හා කුඩා ගල් කුට්ටි පිළිවෙළින් මොනවාද?",
        "මේසා (Mesa) සහ බියුට් (Butte)", "සර්ක් (Cirque) සහ ඇරේට් (Arête)", "ලෙවී (Levee) සහ ඩෙල්ටා (Delta)", "හෝස්ට් (Horst) සහ ග්‍රාබන් (Graben)",
        "මේසාව තවදුරටත් ඛාදනය වී පටු වූ විට කුඩා පැතලි මුදුන් සහිත කුළුණ 'බියුට්' (Butte) නම් වේ."),
      q(t, "සාගර පතුලේ භූ තැටි විභේදන හරහා අධි-උෂ්ණත්ව ඛනිජ ජලය පිටතට විදින ගැඹුරු සාගර වාතාශ්‍රයන් හඳුන්වන්නේ කුමන නමකින්ද?",
        "සාගර පතුලේ බ්ලැක් ස්මෝකර්ස් (Black Smokers)", "ගොඩබිම ගිනිකඳු කලාපවල උණු වතුර විදින ගීසර (Geysers)", "ගිනිකන්දක් කඩා වැටීමෙන් සෑදෙන විශාල කැල්ඩේරා ආවාටය", "සාගර මැද මුදු හැඩැතිව වැඩෙන කොරල් ඇටෝල් දූපත",
        "සූර්යාලෝකය නොමැති ගැඹුරු සාගරයේ පවා රසායනික සංස්ලේෂණය මත යැපෙන ජීවීන් මේ අසල වෙසේ."),
      q(t, "පෘථිවි කබොලේ සමතුලිතතා සිද්ධාන්තය ('Isostasy') මගින් පැහැදිලි කරනු ලබන්නේ කුමක්ද?",
        "සැහැල්ලු මහාද්වීපික කබොල ඝනත්වය වැඩි ප්‍රාවරණය මත පාවෙමින් ගුරුත්ව සමතුලිතතාව රැක ගැනීම", "පෘථිවි භ්‍රමණය හේතුවෙන් මෝසම් සුළං දිශාවන් සෘතු අනුව මාරු වීමේ ක්‍රියාවලිය", "ග්ලැසියර දියවීම නිසා සාගර ජලයේ ලවණතාව කාලයත් සමඟ වෙනස් වීමේ ක්‍රියාවලිය", "සූර්ය තාපය වැඩි වීමෙන් සමක කලාපයේ වායුගෝලීය පීඩන තීරු ඉහළට නැගීම",
        "විශාල ග්ලැසියර දියවී බර අඩු වූ පසු ස්කැන්ඩිනේවියානු භූමිය අදටත් සෙමින් ඉහළ එසවෙන්නේ (Post-glacial Rebound) මෙමගිනි."),
      q(t, "දිගුකාලීන ගංගා නිම්න ඛාදනයේදී ගංගාව සමතුලිත බෑවුමක් (Graded Profile) ලබා ගන්නා විට එහි හැඩය කෙබඳු වේද?",
        "උඩ කඳුකරයේ තියුණු බෑවුමක් සහ මුහුද දෙසට සුමට ලෙස අවතල වූ වක්‍රයක්", "සෑම කිලෝමීටරයකම සමාන උසකින් යුත් සිරස් පඩිපෙළ ආකාරයේ බෑවුමක්", "මූලාශ්‍රයේ පැතලිව පටන් ගෙන මෝය අසලින් ක්ෂණිකව පහළ වැටෙන උත්තල වක්‍රයක්", "ආරම්භයේ සිට මුහුද දක්වාම එකම ආනතියකින් යුත් සරල රේඛීය බෑවුමක්",
        "ඛාදනය හා තැන්පත් වීම සමතුලිත වෙමින් ගංගාව මෘදු අවතල පැතිකඩක් නිර්මාණය කරයි."),
      q(t, "ශ්‍රී ලංකාවේ පැරණි ප්‍රාග්-කේම්බ්‍රියානු ස්ඵටිකරූපී හුණුගල් (Crystalline Limestone) තීරු බහුලව හමුවන ප්‍රදේශ මොනවාද?",
        "මධ්‍යම කඳුකර ආශ්‍රිත මාතලේ, නාලන්ද හා හබරණ ප්‍රදේශ", "උතුරු පළාතේ යාපනය අර්ධද්වීපයේ මයෝසීන හුණුගල් තලාව පමණි", "වයඹ පළාතේ මන්නාරම හා කල්පිටිය වෙරළබඩ වැලි කඳු ප්‍රදේශ", "බස්නාහිර පළාතේ මීගමුව කලපුව හා මුතුරාජවෙල වගුරු බිම් ප්‍රදේශ",
        "මාතලේ හා රත්නපුර දිස්ත්‍රික්කවල ස්ඵටිකරූපී හුණුගල් ස්තර තුළ හුනු කර්මාන්ත හා කුඩා ගුහා පවතී."),
      q(t, "පාංශු ඛාදනය පාලනය කිරීමේ ක්‍රමවලදී 'ආවරණ වගාව' (Cover Cropping) සහ 'වසුන් යෙදීම' (Mulching) වැදගත් වන්නේ ඇයි?",
        "නිරාවරණය වූ පස මත වැසි බිඳු සෘජුව වැදීම වළක්වා පසේ තෙතමනය හා ව්‍යුහය රැක ගැනීමට", "සූර්ය තාපය වැඩි කර පසේ ඇති කාබනික ද්‍රව්‍ය හා තෙතමනය ඉක්මනින් වාෂ්ප කර දැමීමට", "පොළොව යට ඇති දැඩි මව් පාෂාණ ස්තර ඉක්මනින් රසායනිකව දිය කර හැරීමට", "බෑවුම් භූමිය මත සුළං වේගය වැඩි කර මතුපිට පස් තට්ටු ඉවතට ගසා යැවීමට",
        "පස් අංශු ගැලවී යාම (Splash Erosion) නැවැත්වීමට පොළොව මතුපිට ශාක ආවරණය අත්‍යවශ්‍ය වේ."),
      q(t, "සාගර පතුලේ මහාද්වීපික තටාකය සහ අගාධ තැනිතලාව අතර පිහිටි තද බෑවුම හා එහි කැපී ඇති ගැඹුරු නිම්න මොනවාද?",
        "මහාද්වීපික බෑවුම සහ ගැඹුරු සබ්මැරීන් කැන්යොන් නිම්න", "සාගර මධ්‍යයේ පිහිටි ගිනිකඳු මධ්‍ය සාගර වැටිය", "නොගැඹුරු උණුසුම් ජලයේ වැඩෙන බාධක කොරල්පර වැටි", "ගංගා මෝය අසල රොන්මඩ තැන්පත් වන දියළු ඩෙල්ටා තැන්න",
        "කැළඹිලි ධාරා (Turbidity Currents) මගින් මහද්වීපික බෑවුම කැපී ගැඹුරු සබ්මැරීන් කැන්යොන් සාදයි."),
      q(t, "ගංගා නිම්නයක 'ගංගා සෝපාන' (River Terraces) ඇතිවීම පෙන්නුම් කරන්නේ ගංගාවේ කුමන භූ විද්‍යාත්මක ඉතිහාසයක්ද?",
        "මුහුදු මට්ටම බැසීමෙන් හෝ භූමිය එසවීමෙන් පසු ගංගාව පැරණි පිටාර තැන්න කපා පහළට ගැඹුරු වූ බව", "ගංගාවේ ආරම්භයේ සිට කිසිදාක ජල පරිමාවක් හෝ ඛාදනයක් සිදු නොවූ බව", "ගංගා නිම්නය මැද විශාල ආග්නේය ගිනිකන්දක් පුපුරා ලාවා ගලා ගිය බව", "වෙරළබඩ සුළං මගින් කාන්තාර වැලි ගංගා නිම්නය පුරා තැන්පත් කර ඇති බව",
        "මෙය පුනර්ජීවනයේ (Rejuvenation) පැහැදිලි භෞතික සාක්ෂියකි."),
      q(t, "ශ්‍රී ලංකාවේ කඳුකර ප්‍රදේශවල බහුලව සිදුවන 'නායයෑම්' (Landslides) ඇති වීමට බලපාන ප්‍රධාන ප්‍රේරක සාධකය කුමක්ද?",
        "අධික හා අඛණ්ඩ වර්ෂාපතනය නිසා බෑවුම් පස් ස්තර ජලයෙන් සංතෘප්ත වී බර වැඩි වීම", "කඳු මුදුන්වල ග්ලැසියර අයිස් තට්ටු දියවී පහළට කඩා වැටීම", "ශීත සෘතුවේ ඇතිවන දැඩි හිම කුණාටු හා අධික සුළං ධාරා", "වසර පුරා හමන වියළි කාන්තාර වෙළඳ සුළං නිසා පස වියළීම",
        "රත්නපුර, කෑගල්ල, නුවරඑළිය, මහනුවර, බදුල්ල හා කළුතර යන කඳුකර දිස්ත්‍රික්කවල මෙය බහුලය."),
      q(t, "භූ තැටි අභිසාරී සීමාවක සාගරික තැටි දෙකක් (Oceanic-Oceanic) එකිනෙක ගැටුණු විට සාගරය මැද නිර්මාණය වන ප්‍රධාන භූ රූපය කුමක්ද?",
        "ජපානය හා පිලිපීනය වැනි ගිනිකඳු දූපත් චාප", "පැතලි මහාද්වීපික අභ්‍යන්තර සානු ප්‍රදේශ", "ගොඩබිම පිහිටි පුළුල් විභේද නිම්න පද්ධති", "ගංගා මැද පහළ නිම්නයේ සෑදෙන මියැන්ඩර් වංගු",
        "පැරණි ඝන සාගර තැටිය අනෙක් සාගර තැටිය යටට ගිලා බැසීමෙන් මැග්මා ඉහළ නැග දූපත් චාප සාදයි."),
      q(t, "පෘථිවි කබොලේ ප්‍රධාන පාෂාණ සෑදෙන, ක්වාර්ට්ස්, ෆෙල්ඩ්ස්පාර් හා මයිකා අයත් වන ඛනිජ කාණ්ඩය කුමක්ද?",
        "සිලිකේට් ඛනිජ කාණ්ඩය", "සල්ෆේට් ඛනිජ කාණ්ඩය", "කාබනේට් ඛනිජ කාණ්ඩය", "හේලයිඩ් ඛනිජ කාණ්ඩය",
        "ඔක්සිජන් සහ සිලිකන් පෘථිවි කබොලේ වැඩිම ස්කන්ධයක් දරන මූලද්‍රව්‍ය දෙක වන බැවින් සිලිකේට් බහුලය."),
      q(t, "කළුගල් පාෂාණ ජීර්ණය වීමේදී භෞතික හා රසායනික ජීර්ණයට වඩාත්ම ඔරොත්තු දී වැලි බවට පත්ව ඉතිරි වන ඛනිජය කුමක්ද?",
        "ක්වාර්ට්ස් (Quartz)", "කැල්සයිට් (Calcite)", "හැලයිට් (Halite)", "ජිප්සම් (Gypsum)",
        "එබැවින් සියලු පාෂාණ දිරා ගිය පසුද ගංගාවල හා මුහුදු වෙරළේ වැලි ලෙස ඉතිරි වන්නේ බොහෝ විට ක්වාර්ට්ස් කැටය."),
      q(t, "මුහුදු රළ මගින් සිදුවන 'රසායනික දියවී යාම' (Solution) වැඩි වශයෙන්ම සිදු වන්නේ කුමන වෙරළබඩ පාෂාණ තීරවලද?",
        "හුණුගල් හා හුනු මිශ්‍ර පාෂාණ වෙරළ තීරවල", "දැඩි ආග්නේය ග්‍රැනයිට් පාෂාණ වෙරළ තීරවල", "කළු පැහැති බැසෝල්ට් ලාවා වෙරළ තීරවල", "දැඩි විපරීත ක්වාර්ට්සයිට් පාෂාණ වෙරළ තීරවල",
        "මුහුදු ජලයේ ඇති දුර්වල අම්ල කැල්සියම් කාබනේට් සෙමින් දිය කර දමයි."),
      q(t, "භූ රූප විද්‍යාඥයින්ට අනුව ගොඩබිම් මතුපිට භූ විෂමතාව හැඩගැස්වීමට දායක වන වඩාත් පුළුල් හා ප්‍රබලම බාහිර ඛාදන කාරකය කුමක්ද?",
        "ගලා යන ගංගා හා වැසි ජලය (Fluvial Processes)", "වියළි කාන්තාර පෙදෙස්වල හමන සුළං ක්‍රියාවලිය", "ධ්‍රැව හා උස් කඳු මුදුන්වල ගලන ග්ලැසියර ක්‍රියාවලිය", "අභ්‍යවකාශයෙන් පොළොවට වැටෙන උල්කාපාත ඝට්ටන",
        "කාන්තාර පවා ජල මූල ඛාදන රේඛා (Wadis/Alluvial fans) දරන අතර ගංගා භූ දර්ශනයේ ප්‍රධාන නිර්මාපකයා වේ."),
      q(t, "භූ තැටි විද්‍යාවේදී 'පුරා චුම්භකත්වය' (Paleomagnetism) සාගර පතුල පැතිරීම තහවුරු කිරීමට උපකාරී වූයේ කෙසේද?",
        "මධ්‍ය සාගර වැටිය දෙපස බැසෝල්ට් පාෂාණවල චුම්භක දිශානතිය සමමිතික ප්‍රතිවිරුද්ධ තීරු ලෙස සටහන්ව තිබීමෙන්", "විවිධ ගැඹුරුවල සාගර ජල ස්තරවලට ලැබෙන සූර්යාලෝක ප්‍රමාණය හා ජල පීඩනය නිරීක්ෂණය කර මැන බැලීමෙන්", "සාගර පතුලේ තැන්පත්ව ඇති මැරුණු කොරල්පර පොසිලවල සාපේක්ෂ වයස හා රසායනික සංයුතිය ගණනය කිරීමෙන්", "සමකය ආශ්‍රිත ග්‍රහලෝක වෙළඳ සුළං හා සාගර දියවැල් නිරන්තරයෙන් හමන දිශාවන් සිතියම්ගත කිරීමෙන්",
        "පෘථිවි චුම්භක ධ්‍රැව කාලයත් සමඟ මාරු වූ ආකාරය සාගර පතුලේ දෙපස සමාන පටි ලෙස පටිගත වී ඇත."),
      q(t, "සමුද්‍ර මට්ටමට වඩා පහළින් පිහිටි ලෝකයේ ගැඹුරුම ගොඩබිම් විභේද නිම්න පතුල ලෙස සැලකෙන්නේ කුමක්ද?",
        "මුහුදු මට්ටමට මීටර් 430 ක් පමණ පහළින් පිහිටි මළ මුහුදේ වෙරළ තීරය", "ඊජිප්තුව හරහා උතුරට ගලා බසින සාරවත් නයිල් ගංගා නිම්න තැනිතලාව", "හිමාල කඳු පාමුල පිහිටි ඉන්දු-ගංගා දියළු තැනිතලා නිම්න ප්‍රදේශය", "ශ්‍රී ලංකාවේ මධ්‍යම කඳුකරයේ සිට නැගෙනහිරට ගලන මහවැලි ගංගා නිම්නය",
        "ඊශ්‍රායලය හා ජෝර්දානය අතර පිහිටි මළ මුහුද ජෝර්දාන් විභේද නිම්නයේ කොටසකි."),
      q(t, "මහාද්වීපික අයිස් තට්ටු (Ice Sheets) ලෙස වර්තමානයේ පෘථිවිය මත දක්නට ලැබෙන විශාලතම ග්ලැසියර ප්‍රදේශ දෙක මොනවාද?",
        "ඇන්ටාක්ටිකාව සහ ග්‍රීන්ලන්තය", "ඕස්ට්‍රේලියාව සහ අප්‍රිකාව", "දකුණු ඇමරිකාව සහ ඉන්දියාව", "බ්‍රසීලය සහ මෙක්සිකෝව",
        "ලෝකයේ මිරිදිය සංචිතයෙන් 68% කට ආසන්න ප්‍රමාණයක් මෙම අයිස් තට්ටු දෙකෙහි ගබඩා වී පවතී."),
      q(t, "භූමියක සමෝච්ච රේඛා හරහා පොළොව පැතිකඩක් (Cross-Section Profile) ඇඳීමෙන් ලැබෙන ප්‍රධාන භූගෝලීය ප්‍රයෝජනය කුමක්ද?",
        "භූමියේ සැබෑ හැඩය, බෑවුම් ස්වභාවය සහ ස්ථාන දෙකක අන්තර්-දෘශ්‍යතාව පරීක්ෂා කිරීම", "නිශ්චිත කාලසීමාවක් තුළ ප්‍රදේශයකට ලැබෙන වාර්ෂික වර්ෂාපතනය නිවැරදිව මැන ගැනීම", "පරිපාලන දිස්ත්‍රික්කයක ජීවත් වන මුළු ජනගහනය හා ජන ඝනත්වය ගණනය කිරීම", "දේශාංශ ඇසුරින් විවිධ රටවල ප්‍රාමාණික ඔරලෝසු වේලාවන් සසඳා බැලීම",
        "සිතියමේ ස්ථාන දෙකක් එකිනෙකට පෙනේද (Line of Sight) යන්න පැතිකඩ මගින් ස්ථිර කර ගත හැක."),
      q(t, "භූ කම්පන තරංග අතර වැඩිම හානියක් ගොඩනැගිලි හා යටිතල පහසුකම්වලට සිදු කරන, පෘථිවි පෘෂ්ඨය ඔස්සේ ගමන් කරන තරංග මොනවාද?",
        "පෘෂ්ඨීය තරංග (Surface Waves)", "ප්‍රාථමික තරංග (P-Waves)", "ද්විතීයික තරංග (S-Waves)", "අභ්‍යන්තර හර තරංග",
        "Surface waves සෙමින් ගමන් කළද ඒවායේ විස්තාරය හා තිරස්-සිරස් චලනය ඉතා අධික වේ."),
      q(t, "ගංගා ආශ්‍රිත ගංවතුර තැනිතලාවක වසරක් පාසා ගංවතුර බැස යාමෙන් තැන්පත් වන නව රොන්මඩ (Alluvium) පස ගොවිතැනට ඉතා සාරවත් වන්නේ ඇයි?",
        "කඳුකරයෙන් ගෙනෙන ඛනිජ හා කාබනික පෝෂක නිරන්තරයෙන් පසට නැවත එක්වන බැවින්", "මුහුදු ජලය මිශ්‍ර වීමෙන් පසේ ලවණ සාන්ද්‍රණය නිරන්තරයෙන් ඉහළ යන බැවින්", "පසේ තෙතමනය සම්පූර්ණයෙන් ඉවත් වී වියළි වැලි ස්තර පමණක් ඉතිරි වන බැවින්", "ඛාදනයට ලක් නොවන විශාල කළුගල් කුට්ටි පමණක් ගොවිබිමේ තැන්පත් වන බැවින්",
        "මෙසපොතේමියාව, නයිල් නිම්නය හා ඉන්දු නිම්න පුරාණ ශිෂ්ටාචාර බිහිවූයේ මෙම දියළු තැන්න මතය."),
      q(t, "ශ්‍රී ලංකාවේ බෑවුම් ආරක්ෂාව හා නායයෑම් අවම කිරීම සඳහා අවදානම් සිතියම් සහ පූර්ව අනතුරු ඇඟවීම් නිකුත් කරන ජාතික ආයතනය කුමක්ද?",
        "ජාතික ගොඩනැගිලි පර්යේෂණ සංවිධානය (NBRO)", "වනජීවී සංරක්ෂණ දෙපාර්තමේන්තුව", "ශ්‍රී ලංකා කාලගුණ විද්‍යා දෙපාර්තමේන්තුව", "භූ විද්‍යා සමීක්ෂණ හා පතල් කාර්යාංශය",
        "NBRO ආයතනය කඳුකර ඉදිකිරීම් සඳහා භූ විද්‍යාත්මක අනුමැතිය හා පූර්ව නායයෑම් අනතුරු ඇඟවීම් ලබා දේ."),
      q(t, "වෙරළබඩ ප්‍රදේශවල කොරල් හුණුගල් කැඩීම හා වැලි ගොඩදැමීම තහනම් කර ඇත්තේ එමගින් ඇතිවන කුමන භූ රූප විද්‍යාත්මක විනාශය වැළැක්වීමටද?",
        "මුහුදු රළ ශක්තිය වැඩි වී වෙරළ තීරය වේගයෙන් ඛාදනය වීම හා ගොඩබිම අහිමි වීම", "වෙරළබඩ ප්‍රදේශවල ස්වාභාවික ලුණු නිෂ්පාදනය හා වාෂ්පීකරණය සම්පූර්ණයෙන් නතර වීම", "සාගර පතුලේ අභ්‍යන්තර ගිනිකඳු සක්‍රීය වී නව දූපත් හදිසියේම ඉහළට මතු වීම", "කඳුකර ප්‍රදේශවල භූමිකම්පා ඇති වී ගංගා ගලා යන දිශාවන් සම්පූර්ණයෙන් වෙනස් වීම",
        "කොරල්පර ස්වාභාවික තරංග කඩනයක් (Breakwater) ලෙස ක්‍රියා කර වෙරළට එන රළ ශක්තියෙන් 80% කට වඩා අඩු කරයි."),
      q(t, "පෘථිවි පෘෂ්ඨයේ උසම කඳු වැටිය හිමාලය වුවද, සාගර පතුලේ පාදමේ සිට මැන බැලුවහොත් ලොව උසම ස්වාභාවික ගිනි කන්ද කුමක්ද?",
        "හවායි දූපතේ පිහිටි මවුනා කියා කන්ද", "ජපානයේ හොන්ෂු දූපතේ පිහිටි ෆුජි කන්ද", "ඉතාලියේ සිසිලි දූපතේ පිහිටි එට්නා කන්ද", "ශ්‍රී ලංකාවේ නුවරඑළියේ පිහිටි පිදුරුතලාගල කන්ද",
        "මවුනා කියා හි මුදුන මුහුදු මට්ටමෙන් මීටර් 4,207 ක් වුවද එහි පාදම මීටර් 6,000 ක් ගැඹුරු පැසිෆික් පතුලේ පිහිටයි."),
      q(t, "මුහුදු ගිනිකඳු දූපතක් ක්‍රමයෙන් ගිලා බැස වෙරළබඩ කොරල්පරය 'වෙරළ පරය, බාධක පරය හා ඇටෝල්' ලෙස පරිණාමය වන බව පෙන්වා දුන් විද්‍යාඥයා කවුද?",
        "චාල්ස් ඩාවින් (Charles Darwin)", "ඇල්ෆ්‍රඩ් වෙගනර් (Alfred Wegener)", "අයිසැක් නිව්ටන් (Isaac Newton)", "ගැලීලියෝ ගැලිලි (Galileo Galilei)",
        "ඩාවින්ගේ මෙම ගිලා බැසීමේ කොරල්පර න්‍යාය පසුකාලීන ගැඹුරු විදුම් පරීක්ෂණවලින් තහවුරු විය."),
      q(t, "ශ්‍රී ලංකාවේ මධ්‍යම කඳුකරයේ සිට ගලා යන ගංගාවල ජල විදුලි බලාගාර ඉදිකිරීමට පහසු වූ භූ රූප විද්‍යාත්මක සාධකය කුමක්ද?",
        "සානු මට්ටම් අතර පිහිටි තියුණු බෑවුම්, දිය ඇලි සහ පටු ගල් දුර්ග", "සමුද්‍ර මට්ටමේ පිහිටි පුළුල් ඩෙල්ටා තැනිතලා හා මඩ වගුරු බිම්", "වියළි කලාපයේ මයෝසීන හුණුගල් තුළ පවතින භූගත කාර්ස්ට් ගුහා", "වෙරළ තීරය දිගේ සුළඟින් නිර්මාණය වූ පැතලි වැලි කඳු වැටි",
        "ලක්ෂපාන, වික්ටෝරියා, කොත්මලේ සහ සමනලවැව ජලාශ මෙම භූ විෂමතාව ප්‍රයෝජනයට ගෙන ඉදිකර ඇත."),
      q(t, "කඳුකර වගා බිම්වල මතුපිට පස් රූරා යාම හා සේදී යාම වැළැක්වීම සඳහා ගොවීන් යොදා ගන්නා ඵලදායී පාංශු සංරක්ෂණ ක්‍රමය කුමක්ද?",
        "සමෝච්ච හෙල්මළු සැකසීම සහ සැවැන්දරා වැනි තෘණ වැටි වැවීම", "බෑවුම මුදුනේ සිට පහළට සෘජුවම ගැඹුරු ජල බැසීමේ කාණු කැපීම", "බෑවුමේ පවතින සියලුම ස්වාභාවික ශාක හා පඳුරු කපා පිළිස්සීම", "අධික වර්ෂාව පවතින කාලවලදී බර යන්ත්‍ර මගින් බෑවුම් පස බුරුල් කිරීම",
        "සැවැන්දරා තෘණ පඳුරුවල ගැඹුරු තන්තුමය මුල් පස ස්ථාවර කර මතුපිට පස් සේදී යාම වළකයි."),
      q(t, "භූ තැටි විද්‍යාවට අනුව පෘථිවි භූ තැටි සාමාන්‍යයෙන් වසරකට කවර වේගයකින් පමණ චලනය වේද?",
        "සෙන්ටිමීටර 2 සිට 10 දක්වා ඉතා සෙමින්", "කිලෝමීටර් 50 සිට 100 දක්වා වේගයෙන්", "මීටර් 200 සිට 500 දක්වා වේගයෙන්", "කිසිදු චලනයක් නොමැතිව සම්පූර්ණයෙන්ම නිශ්චලව",
        "නවීන GPS ස්ථානගත කිරීම් මගින් මෙම මිලිමීටර් හා සෙන්ටිමීටර් මට්ටමේ භූ තැටි චලනය නිවැරදිව මැනිය හැක."),
      q(t, "පොළොව යට ඇති පාෂාණ ද්‍රව නොවී වෙනස් ස්වභාවයකට පත් වන 'විපරීතභාවය' (Metamorphism) සිදුවීමට බලපාන ප්‍රධාන සාධක මොනවාද?",
        "අධික තාපය, අධික පීඩනය සහ රසායනිකව ක්‍රියාකාරී තරල", "වායුගෝලීය සීතල, හිම පතනය සහ තුහින පැලීම", "වෙරළබඩ සුළං ප්‍රවාහය, වර්ෂාව සහ රළ පහර", "දිවා කාලයේ සූර්යාලෝකය සහ රාත්‍රී පින්න",
        "මැග්මා ආක්‍රමණ අසලදී Contact Metamorphism ද කඳු ගොඩනැගීමේදී Regional Metamorphism ද සිදුවේ."),
      q(t, "ලෝකයේ ගැඹුරුම මිරිදිය විල වන රුසියාවේ 'බයිකල් විල' (Lake Baikal) නිර්මාණය වී ඇත්තේ කුමන භූ රූප විද්‍යාත්මක ක්‍රියාවලියෙන්ද?",
        "මහාද්වීපික විභේද නිම්නයක් (Rift Valley) මිරිදිය ජලයෙන් පිරීමෙන්", "සාගර මැද කොරල්පර මුදු හැඩයට ඉහළට වැඩීමෙන්", "වෙරළබඩ වැලි තුඩුවකින් මුහුදු බොක්කක් සම්පූර්ණයෙන් වැසී යාමෙන්", "කාන්තාර පෙදෙසක අඩසඳ හැඩැති බාචන් වැලි කඳු තැනීමෙන්",
        "මීටර් 1,642 ක් ගැඹුරු බයිකල් විල ලෝකයේ ද්‍රව මිරිදිය ජලයෙන් 20% ක් පමණ දරා සිටී."),
      q(t, "මුහුදු වෙරළේ 'ඛනිජ වැලි' (ශ්‍රී ලංකාවේ පුල්මුඩේ ඉල්මනයිට් හා රූටයිල් වැනි) ස්වාභාවිකව එක්රැස් වන්නේ කෙසේද?",
        "ගංගාවලින් ගෙනෙන ජීර්ණ වූ බර ඛනිජ මුහුදු රළ හා වෙරළ ප්‍රවාහයෙන් වෙන්වී තැන්පත් වීමෙන්", "සක්‍රීය ගිනිකඳු පිපිරීමෙන් ගුවනට විසි වන අළු මුහුදු වෙරළේ ඝන වීමෙන්", "වායුගෝලයේ ජල වාෂ්ප ඝනීභවනය වී වර්ෂාව සමඟ වෙරළට පතිත වීමෙන්", "නොගැඹුරු සාගරයේ කොරල්පර ජීවීන් මිය ගොස් වැලි බවට පත් වීමෙන්",
        "සැහැල්ලු ක්වාර්ට්ස් වැලි ඉවතට ගසා යන අතර බර ටයිටේනියම් ඛනිජ වැලි වෙරළේ තැන්පත් වේ."),
      q(t, "ගොඩබිම් ස්ථානයක භූගත ජල මට්ටම (Water Table) වැසි කාලයේදී සහ වියළි කාලයේදී වෙනස් වන්නේ කෙසේද?",
        "වැසි කාලයේදී පොළොව මතුපිටට ආසන්න වන අතර නියඟයේදී ගැඹුරට බැස යයි", "සෘතු වෙනස් වුවද සැමවිටම එකම ගැඹුර මට්ටමක නොවෙනස්ව පවතී", "නියඟයේදී පීඩනය වැඩි වී පොළොව මතුපිටින් ඉහළට උතුරා ගලා යයි", "වැසි කාලයේදී සම්පූර්ණයෙන් වාෂ්ප වී භූගත පාෂාණ වියළී යයි",
        "ජල මට්ටමට පහළින් ඇති සියලු පාෂාණ සිදුරු ජලයෙන් පිරුණු කලාපය 'සංතෘප්ත කලාපය' (Zone of Saturation) නම් වේ."),
      q(t, "ග්ලැසියරයක් ගමන් කිරීමේදී පාෂාණ ගැටයක එක් පැත්තක් සිනිඳු වී අනෙක් පැත්ත රළු ලෙස කැඩී යාමෙන් සෑදෙන භූ ලක්ෂණය කුමක්ද?",
        "රොෂ් මුටෝනේ (Roche Moutonnée)", "සමුද්‍ර ටැඹ (Sea Stack)", "ගංගා ඉවුරු ලෙවී වැටිය", "කාන්තාර බාචන් වැලි කන්ද",
        "ග්ලැසියරය එන පැත්ත සිනිඳු ඝර්ෂණයෙනුත් (Abrasion) පිටවන පැත්ත ගැලවී යාමෙනුත් (Plucking) රළු වී ඇත."),
      q(t, "භූගෝල විද්‍යාවේදී 'පස ලවණීකරණය' (Soil Salinization) බහුලව සිදු වන්නේ කුමන පාරිසරික තත්ත්ව යටතේද?",
        "අධික වාෂ්පීකරණයක් ඇති වියළි පෙදෙස්වල ජල බැස්මක් නොමැතිව අධික ජල සම්පාදනය කිරීමෙන්", "වසර පුරා අධික වර්ෂාව ලැබෙන සමක නිවර්තන වැසි වනාන්තර කලාපවල", "නිරන්තර හිම පතනයක් පවතින උස් කඳු මුදුන් හා ධ්‍රැව කලාපවල", "කෙටි ගිම්හානයක් පමණක් පවතින ආක්ටික් ටුන්ඩ්‍රා තෘණ බිම්වල",
        "ජලය වාෂ්ප වී භූගත ලවණ කේශික ක්‍රියාවෙන් මතුපිට රැඳී පස වගාවට නුසුදුසු වේ."),
      q(t, "විශාල ගොඩනැගිලි හා වේලි ඉදිකිරීමේදී අත්තිවාරම් සඳහා වඩාත්ම ශක්තිමත් 'දැඩි බිම් ආධාරක' (Bedrock) පාෂාණය කුමක්ද?",
        "නොදිරූ දැඩි ග්‍රැනයිට් හෝ නයිස් පාෂාණය", "ජලය උරා ගන්නා බුරුල් මැටි පස", "කාබනික ද්‍රව්‍ය බහුල තෙත් පීට් තට්ටුව", "වෙරළබඩ ලවණ මඩ සහ සියුම් වැලි තට්ටුව",
        "අත්තිවාරම් සඳහා නොදිරූ ස්ඵටිකරූපී පාෂාණ ස්තරය ඉහළම දරාගැනීමේ ශක්තිය සපයයි."),
      q(t, "උතුරු අයර්ලන්තයේ Giant's Causeway වැනි ෂඩාස්‍රාකාර බැසෝල්ට් ගල් කුළුණු ස්වාභාවිකව නිර්මාණය වන්නේ කෙසේද?",
        "ඝන බැසෝල්ට් ලාවා තට්ටුවක් ඒකාකාරව සිසිල් වී හැකිලීමේදී ඇතිවන ඉරිතැලීම් මගින්", "පුරාණ මිනිසුන් විසින් යකඩ ආයුධ යොදා ගෙන ගල් කැටයම් කර කැපීමෙන්", "ග්ලැසියර අයිස් තට්ටු ඝන වී පාෂාණ මත අධික පීඩනයක් යෙදීමෙන්", "මුහුදු රළ මගින් සියුම් වැලි හා සිප්පි කටු තට්ටු ලෙස තැන්පත් කිරීමෙන්",
        "උතුරු අයර්ලන්තයේ Giant's Causeway මෙවැනි ස්වාභාවික ෂඩාස්‍රාකාර ලාවා කුළුණු සඳහා ලෝක උරුමයකි."),
      q(t, "මුහුදු වෙරළක ගංගා මෝයකින් එන වැලි හා රළ පහර අතර සමතුලිතතාව බිඳ වැටී වෙරළ ඛාදනය උග්‍ර වීමට ප්‍රධාන මානව හේතුව කුමක්ද?",
        "ගංගාවල අවිධිමත් වැලි ගොඩදැමීම හා ඉහළ ජලාශ ඉදිකිරීමෙන් වෙරළට එන වැලි අඩු වීම", "කඳුකර ජල පෝෂක ප්‍රදේශවල වාර්ෂික වර්ෂාපතනය සාමාන්‍යයට වඩා වැඩි වීම", "ගංගා ඉවුරු දෙපස පස රැක ගැනීම සඳහා කුඹුක් හා උණ ගස් රෝපණය කිරීම", "මුහුදු මෝය ආශ්‍රිත තෙත් බිම්වල ස්වාභාවික කඩොලාන පරිසර පද්ධති ආරක්ෂා කිරීම",
        "කැලණි, මහ ඔය හා දැදුරු ඔය මෝය අවට වෙරළ ඛාදනයට අධික ගංගා වැලි ගොඩදැමීම හේතු වී ඇත."),
      q(t, "විශාල ගංගාවක ඉහළ ජල පෝෂක ප්‍රදේශයේ (Catchment Area) වනාන්තර හෙළි කළ විට පහළ ගංගා නිම්නයට ඇතිවන බලපෑම කුමක්ද?",
        "පස සෝදාපාළුවී ගංගාව රොන්මඩින් පිරී ගැඹුර අඩු වීමත් හදිසි ගංවතුර උග්‍ර වීමත්", "ගංගා ජලයේ රොන්මඩ ඉවත් වී ජලය වඩාත් පිරිසිදු හා පැහැදිලි වීම", "ගංගාවේ ඉහළ නිම්නයේ පිහිටි සියලුම ස්වාභාවික දිය ඇලි අතුරුදන් වීම", "ගංගාවේ ජල ප්‍රවාහය වසර පුරාම කිසිදු වෙනසකින් තොරව ස්ථිරව පැවතීම",
        "එබැවින් ඉහළ ජල පෝෂක වනාන්තර ආරක්ෂා කිරීම ගංවතුර පාලනයට සෘජුව උපකාරී වේ."),
      q(t, "ගංගාවක ප්‍රවාහන ධාරිතාව (Competence) ගංගා ජල ප්‍රවේගය මත රඳා පවතින ආකාරය කුමක්ද?",
        "ජල ප්‍රවේගය වැඩි වන විට ගෙන යා හැකි පාෂාණ කැබලිවල විශාලත්වය තීව්‍ර ලෙස ඉහළ යයි", "ජල ප්‍රවේගය අඩු වන විට ගංගාවට වඩාත් විශාල ගල් කුට්ටි පෙරළා ගෙන යා හැකිය", "ගංගා ජල ප්‍රවේගය ගංගාවේ ඛාදන හෝ ප්‍රවාහන හැකියාව කෙරෙහි කිසිසේත් බල නොපායි", "ගමන් වේගයක් නොමැති නිශ්චල ජලාශ ජලය විශාල ගල් කුට්ටි පහසුවෙන් ගෙන යයි",
        "එබැවින් ගංවතුර අවස්ථාවේදී ගංගාවකට සාමාන්‍ය කාලයට වඩා කිහිප ගුණයකින් විශාල ගල් පෙරළා ගෙන යා හැක."),
      q(t, "මුහුදු වෙරළ තීරයක දැඩි හා මෘදු පාෂාණ විකල්පව පිහිටි විට මුහුද දෙසට නෙරා සිටින දැඩි පාෂාණ කොටස හඳුන්වන්නේ කුමන නමින්ද?",
        "දෙවුන්දර තුඩුව වැනි වෙරළබඩ තුඩුව (Headland)", "කිවුල් දිය පිරුණු වෙරළබඩ කලපුව (Lagoon)", "කාන්තාර පෙදෙසක වියළි ගංගා නිම්නයක් වන වඩි (Wadi)", "ග්ලැසියර කඳු ආරම්භයේ සැකසුණු සර්ක් අවපාතය (Cirque)",
        "ප්‍රතිරෝධී පාෂාණ මුහුදු රළට ඔරොත්තු දී මුහුද දෙසට නෙරා සිටීමෙන් තුඩු නිර්මාණය වේ."),
      q(t, "පෘථිවි ඉතිහාසයේ භූ තැටි එකිනෙක ගැටී කඳු පද්ධති ගොඩනැගීමේ ක්‍රියාවලිය භූ විද්‍යාවේදී හඳුන්වන්නේ කුමන නමකින්ද?",
        "ඔරොජෙනි හෙවත් ගිරිජනනය (Orogeny)", "මහාද්වීප සෙමින් එසවෙන එපයිරොජෙනි (Epeirogeny)", "ඛනිජ වායුගෝලීය ඔක්සිකරණය (Oxidation)", "අවසාදිත පාෂාණ ඝන වීමේ ලිතිෆිකරණය (Lithification)",
        "කැලිඩෝනියන්, හර්සීනියන් සහ ඇල්පයින් යනු පෘථිවියේ ප්‍රධාන කඳු ගොඩනැගීමේ යුග (Orogenies) තුනකි."),
      q(t, "හිම යුගයේදී කැපුණු ගැඹුරු ග්ලැසියර නිම්න අයිස් දියවීමෙන් පසු මුහුදු ජලයෙන් යටවී සෑදෙන පටු මුහුදු ඇතුළු වීම් මොනවාද?",
        "නෝර්වේ වෙරළේ දක්නට ලැබෙන ෆියෝඩ් (Fjords)", "වියළි කාන්තාරවල පවතින වියළි වඩි ගංගා නිම්න", "ගංගා ඉවුරු දෙපස රොන්මඩ තැන්පත් වන ලෙවී වැටි", "සුළඟින් වැලි තැන්පත් වී හැදෙන බාචන් වැලි කඳු",
        "ෆියෝඩ් මෝය ආසන්නයේ නොගැඹුරු පාෂාණ පඩියක් (Threshold) තිබුණද ඇතුළත ඉතා ගැඹුරු වේ."),
      q(t, "පෘථිවි කබොලේ විභේදන ක්‍රියාකාරිත්වය නිසා 'කුට්ටි කඳු' (Block Mountains) නිර්මාණය වීමට හේතුව කුමක්ද?",
        "ආතති හෝ සම්පීඩන බල නිසා විභේදන ඇතිවී මැද කොටස ඉහළට එසවීම", "විශාල ග්ලැසියර අයිස් තට්ටු දියවී කඳු මුදුන් කැපී පහළට යාම", "කාන්තාර සුළඟින් සියුම් වැලි ගොඩගැසී විශාල කඳු පන්ති නිර්මාණය වීම", "නොගැඹුරු සාගරයේ කොරල්පර වැඩී මුහුදු මට්ටමෙන් ඉහළට මතු වීම",
        "ජර්මනියේ බ්ලැක් ෆොරස්ට් (Black Forest) සහ ඉන්දියාවේ වින්ධ්‍යා-සත්පුර කඳු කුට්ටි කඳු සඳහා උදාහරණ වේ."),
      q(t, "ගංගා මැද හා පහළ නිම්නවල ඇති වන 'ගංවතුර තැනිතලාව' (Floodplain) මතුපිට සාරවත් රොන්මඩ තැන්පත් වීමට හේතුව කුමක්ද?",
        "වැසි සමයේ ගංගාව ඉවුරු පිටාර ගොස් වේගය අඩු වී රොන්මඩ නිම්නය පුරා තැන්පත් වීම", "ප්‍රබල කාන්තාර සුළං මගින් දුර බැහැර සිට වැලි ගසාගෙන විත් තැන්පත් කිරීම", "අසල පිහිටි ගිනිකඳුවලින් නිකුත් වන උණු ලාවා නිම්නය පුරා ගලා යාම", "ශීත සෘතුවේ ගංගා ජලය අයිස් බවට මිදී ඉවුරු මත පස් තල්ලු කිරීම",
        "මෙම පිටාර තැනිතලා බහුලව කෘෂිකර්මාන්තය සඳහා භාවිත කෙරුණද නාගරික ඉදිකිරීම්වලදී ගංවතුර අවදානම දරයි."),
      q(t, "ගංගාවක් දැඩි බෑවුමක සිට ගලා යන අතරතුර ඒ මාර්ගයේ දැඩි හා මෘදු පාෂාණ තීරු හමුවූ විට ඇතිවන කුඩා වේගවත් රළ බිඳුම් කලාපය කුමක්ද?",
        "රැපිඩ්ස් හෙවත් දිය ඇළි පෙළ (Rapids)", "මියැන්ඩර් නම් ගංගා වංගු (Meanders)", "මෝය අසල ඩෙල්ටා තැනිතලාව (Delta)", "ස්වාභාවික ගං ඉවුරු ලෙවී වැටිය (Levee)",
        "ජල ක්‍රීඩා (White-water Rafting) සඳහා ශ්‍රී ලංකාවේ කිතුල්ගල කැලණි ගඟේ මෙවැනි Rapids කලාප යොදා ගනී."),
      q(t, "මුහුදු වෙරළේ තරංග ඛාදනය නිසා තුඩුවක මුහුදු ගුහා දෙකක් ඇතුළතින් හමුවී පාෂාණය හරහා විවරයක් සෑදුණු විට එය හඳුන්වන්නේ කුමක් ලෙසද?",
        "සමුද්‍ර ආරුක්කුව (Sea Arch)", "හුදෙකලා සමුද්‍ර ටැඹ (Sea Stack)", "වැලි වැටියෙන් වටවූ කලපුව (Lagoon)", "දූපතක් යා කරන ටොම්බොලෝ වැටිය (Tombolo)",
        "ආරුක්කුවේ ඉහළ වහලය කඩා වැටුණු පසු එය මුහුදු ටැඹක් (Sea Stack) බවට පත්වේ."),
      q(t, "කාන්තාරයක වැලි සහිත සුළඟින් ගල් කැබලිවල පැති මුහුණත් ඔප දැමීමෙන් පසු ඉතිරි වන කෝණාකාර සුමට ගල් කැබලි මොනවාද?",
        "වෙන්ටිෆැක්ට්ස් (Ventifacts)", "ගුහා වහලයේ එල්ලෙන ස්ටැලක්ටයිට්", "ග්ලැසියර පතුලේ සැකසෙන ඩ්‍රම්ලින්ස්", "ග්ලැසියර පාමුල තැන්පත් මොරේන්",
        "වැලි සහිත සුළං දිශාවන් මගින් ගල් කැබලිවල පැති මුහුණත් ඔප දැමීමෙන් Ventifacts නිර්මාණය වේ."),
      q(t, "භූමිකම්පාවකදී පොළොව යට ඇති ඝන හා ද්‍රව ස්තර හඳුනා ගැනීමට විද්‍යාඥයින් භාවිත කරන 'සෙවණැලි කලාපය' (Shadow Zone) යනු කුමක්ද?",
        "භූ කම්පන නාභියට 105° සිට 140° දක්වා P හා S තරංග සෘජුව වාර්තා නොවන පෘථිවි කලාපය", "නිවර්තන සුළි සුළඟක මධ්‍යයේ පිහිටි සුළං හා වැසි රහිත නිශ්චල ඇස කලාපය", "උස් කඳු වැටියක සුළං මුවා පැත්තේ පිහිටි වියළි වැසි මුවා කලාපය", "සූර්ය ග්‍රහණයකදී චන්ද්‍රයාගේ පූර්ණ සෙවණැල්ල පෘථිවිය මත පතිත වන අඳුරු කලාපය",
        "P තරංග වර්තනය වීමත් S තරංග ද්‍රව පිටත හරයෙන් අවහිර වීමත් නිසා මෙම Shadow Zone ඇතිවේ."),
      q(t, "සාගර පතුලේදී නිර්මාණය වන නව සාගරික කබොල මහාද්වීපික කබොලට වඩා ඝනත්වයෙන් වැඩි වන්නේ ඇයි?",
        "සාගරික කබොල බර බැසෝල්ට් (SIMA) වලින්ද මහාද්වීපික කබොල සැහැල්ලු ග්‍රැනයිට් (SIAL) වලින්ද සැදී ඇති බැවින්", "සාගරික කබොල ඉහළ උෂ්ණත්වයේදී ප්ලාස්ටික් මෙන් ඇදෙන සුළු බවකින් හා අඩු පීඩනයකින් යුක්ත වන බැවින්", "මහාද්වීපික කබොල ඇතුළත සම්පූර්ණයෙන් හිස් වායු කුහර හා ජල ගුහාවලින් පිරී සැහැල්ලුව පවතින බැවින්", "සාගර ජලයේ ඇති අධික ලවණතාව හා සීතල නිසා පතුලේ පාෂාණ සැමවිටම බරින් වැඩි වන බැවින්",
        "එම වැඩි ඝනත්වය නිසා අභිසාරී සීමාවේදී සාගරික තැටිය මහාද්වීපික තැටිය යටට ගිලා බසී."),
      q(t, "හුණුගල් ගුහාවක සිවිලිම කඩා වැටී ඉහළින් ආලෝකය වැටෙන හා ජලය පිරුණු විශාල ගිලා බැසීමේ විවරයක් හඳුන්වන්නේ කෙසේද?",
        "ඩොලයින් හෙවත් සිනෝටේ (Doline / Cenote)", "ගිනිකඳු කැල්ඩේරා ආවාටය (Caldera)", "ගංගා වංගු වෙන්වූ ඔක්ස්බෝ විල (Oxbow Lake)", "භූතාපජ උණු වතුර ගීසරය (Geyser)",
        "ගුහා වහලය කඩා වැටීමෙන් පාතාල භූගත ජලය මතුපිටට විවෘත වූ විට මෙවැනි ස්වාභාවික ළිං සෑදේ."),
      q(t, "පාංශු සංරක්ෂණයේදී 'පටි වගාව' (Strip Cropping) මගින් බෑවුම් භූමිවල ඛාදනය පාලනය කරන්නේ කෙසේද?",
        "වැඩි පසක් නිරාවරණය වන භෝග හා ඝන ආවරණ භෝග සමෝච්ච රේඛා දිගේ මාරුවෙන් මාරුවට වැවීමෙන්", "බෑවුමේ පවතින සියලුම විශාල ගස් හා ස්වාභාවික ශාක ආවරණය සම්පූර්ණයෙන් ඉවත් කිරීමෙන්", "වගා කිරීමට පෙර බෑවුමේ වියළි තණකොළ හා මතුපිට පස ගිනි තබා පුළුස්සා දැමීමෙන්", "වැසි ජලය ඉක්මනින් පහළට බැස යාමට බෑවුම ඉහළ සිට පහළට කෙළින් සීසෑමෙන්",
        "ඝන තෘණ පටි ගලා යන රොන්මඩ සහිත ජලය අල්ලා රඳවා ගනී."),
      q(t, "ගංගා ඉවුරු ඛාදනය වැළැක්වීම සඳහා 'කුඹුක්' (Terminalia arjuna) වැනි ගංගාධාර ශාක වැදගත් වන්නේ ඇයි?",
        "ගං ඉවුරු පස තදින් බැඳ තබන ශක්තිමත් මූල පද්ධතියක් පැවතීම හා ජලය පිරිසිදු කිරීම", "ගං ඉවුරු පසෙහි ලවණ සාන්ද්‍රණය වැඩි කර පස ඝන ගල් බවට පත් කිරීම", "ගංගාවේ ගලා යන ජලය සම්පූර්ණයෙන් උරා ගෙන ගංගාව ඉක්මනින් වියළා දැමීම", "වැසි කාලයේදී ගංගා පතුලේ විශාල පාෂාණ කැබලි අලුතින් නිර්මාණය කිරීම",
        "ශ්‍රී ලංකාවේ ගංගා හා වැව් තාවුලු ආරක්ෂා කිරීමට කුඹුක් ගස් සාම්ප්‍රදායිකව රෝපණය කෙරේ."),
      q(t, "ගිනිකඳු ආවාටයක සිරස් නළය තුළ ඝන වූ දැඩි පාෂාණය වටා ඇති මෘදු අළු කේතුව ඛාදනය වූ පසු ඉතිරි වන ගල් කුළුණ කුමක්ද?",
        "ගිනිකඳු ප්ලග් හෙවත් බෙල්ල (Volcanic Plug)", "ගංගා මෝයේ දියළු ඩෙල්ටාව (Delta)", "දූපතක් යා කරන ටොම්බොලෝව (Tombolo)", "ගුහා පතුලෙන් ඉහළට වැඩෙන ස්ටැලග්මයිට්",
        "ඇමරිකාවේ නිව් මෙක්සිකෝ හි 'ෂිප්රොක්' (Shiprock) සහ ස්කොට්ලන්තයේ එඩින්බරෝ බලකොටු පර්වතය මීට උදාහරණ වේ."),
      q(t, "කඳුකර ප්‍රදේශවල හිම හා ග්ලැසියර පසුබසින විට පාෂාණ තට්ටු මත ඉතිරි කරන සමාන්තර සීරීම් රේඛා හඳුන්වන්නේ කුමන නමකින්ද?",
        "ග්ලැසියර සීරීම් (Glacial Striations)", "අඩසඳ හැඩැති බාචන් වැලි කඳු", "ගංගා ඉවුරේ ලෙවී වැලි වැටි", "වෙරළ වැලි මත රළ රිපල් සලකුණු",
        "ග්ලැසියර පතුලේ සිරවූ ගල් කැබලි පාෂාණ පෘෂ්ඨය මත සීරීම් ඇති කරමින් අතීත ග්ලැසියර ගමන් දිශාව පෙන්වයි.")
    )
  }
}

